import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { useStore } from '../context/Store';
import { TRANSLATIONS, CATEGORIES } from '../constants';
import { Briefcase, TrendingUp, CheckCircle, AlertCircle } from 'lucide-react';

export const Signup: React.FC = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { lang } = useStore();
  const t = TRANSLATIONS[lang].auth;

  // Default to investor if not specified
  const role = searchParams.get('role') === 'company' ? 'company' : 'investor';

  // Helper to get demo defaults based on role
  const getDefaults = (currentRole: string) => {
    if (currentRole === 'company') {
      return {
        firstName: 'محمد',
        lastName: 'العتيبي',
        email: 'company.test@bi.com',
        phone: '88880000',
        companyName: 'شركة المستقبل للاستثمار',
        companyAge: '5',
        sector: 'Technology & SaaS', 
        valuation: '250000',
        investorType: '',
        // New Fields
        legalEntity: 'LLC',
        companyType: 'Startup',
        requestedInvestment: '50000',
        investmentReason: 'Expansion into GCC market',
        shareToSell: '20',
        fullDetails: 'Detailed breakdown of SaaS product roadmap, user acquisition strategy, and 5-year financial projections.'
      };
    }
    return {
      firstName: 'أحمد',
      lastName: 'الشمري',
      email: 'investor.test@bi.com',
      phone: '99990000',
      companyName: '',
      companyAge: '',
      sector: '',
      valuation: '',
      investorType: 'individual',
      // Reset new fields
      legalEntity: '',
      companyType: '',
      requestedInvestment: '',
      investmentReason: '',
      shareToSell: '',
      fullDetails: ''
    };
  };

  const [formData, setFormData] = useState(getDefaults(role));
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    // Reset form and errors when role changes
    setFormData(getDefaults(role));
    setErrors({});
  }, [role]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    // For phone, only allow digits and max 8
    if (name === 'phone') {
      if (!/^\d*$/.test(value)) return;
      if (value.length > 8) return;
    }
    setFormData(prev => ({ ...prev, [name]: value }));
    // Clear error for field
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!formData.firstName.trim()) newErrors.firstName = t.required;
    if (!formData.lastName.trim()) newErrors.lastName = t.required;
    if (!formData.email.trim()) {
      newErrors.email = t.required;
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = t.invalidEmail;
    }

    if (!formData.phone.trim()) {
      newErrors.phone = t.required;
    } else if (formData.phone.length !== 8) {
      newErrors.phone = t.invalidPhone;
    }

    if (role === 'company') {
      if (!formData.companyName.trim()) newErrors.companyName = t.required;
      if (!formData.companyAge.trim()) newErrors.companyAge = t.required;
      if (!formData.sector.trim()) newErrors.sector = t.required;
      // if (!formData.valuation.trim()) newErrors.valuation = t.required; // Valuation might be optional if requestedInvestment is primary

      if (!formData.legalEntity.trim()) newErrors.legalEntity = t.required;
      if (!formData.companyType.trim()) newErrors.companyType = t.required;
      if (!formData.requestedInvestment.trim()) newErrors.requestedInvestment = t.required;
      if (!formData.investmentReason.trim()) newErrors.investmentReason = t.required;
      if (!formData.shareToSell.trim()) newErrors.shareToSell = t.required;
      if (!formData.fullDetails.trim()) newErrors.fullDetails = t.required;
    }

    if (role === 'investor' && !formData.investorType) {
        newErrors.investorType = t.required;
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validate()) {
      setIsSubmitting(true);
      // Simulate API call
      setTimeout(() => {
        setIsSubmitting(false);
        navigate('/verify-email');
      }, 1500);
    }
  };

  return (
    <div className="min-h-[85vh] flex items-center justify-center px-4 py-12">
      <div className="max-w-2xl w-full bg-brand-gray/20 border border-white/10 rounded-2xl p-8 backdrop-blur-sm animate-fade-in">

        {/* Header */}
        <div className="text-center mb-10">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-brand-gold/10 text-brand-gold mb-4">
             {role === 'company' ? <Briefcase size={32} /> : <TrendingUp size={32} />}
          </div>
          <h2 className="text-3xl font-bold text-white mb-2">
            {role === 'company' ? t.company : t.investor}
          </h2>
          <p className="text-gray-400 max-w-md mx-auto">
            {role === 'company' ? t.companySubtitle : t.investorSubtitle}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">

          {/* Investor Type Segmented Control */}
          {role === 'investor' && (
            <div className="space-y-2 animate-fade-in">
              <label className="text-sm font-medium text-gray-300">{t.investorType} <span className="text-brand-gold">*</span></label>
              <div className="flex bg-black/50 p-1 rounded-xl border border-white/10">
                <button
                  type="button"
                  onClick={() => setFormData(prev => ({ ...prev, investorType: 'individual' }))}
                  className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all duration-300 ${formData.investorType === 'individual' ? 'bg-brand-gold text-black shadow-lg shadow-brand-gold/20' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
                >
                  {t.individual}
                </button>
                <button
                  type="button"
                  onClick={() => setFormData(prev => ({ ...prev, investorType: 'institution' }))}
                  className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all duration-300 ${formData.investorType === 'institution' ? 'bg-brand-gold text-black shadow-lg shadow-brand-gold/20' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
                >
                  {t.institution}
                </button>
              </div>
            </div>
          )}

          {/* Common Fields */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-300">{t.firstName} <span className="text-brand-gold">*</span></label>
              <input 
                type="text" 
                name="firstName" 
                value={formData.firstName}
                onChange={handleChange}
                className={`w-full bg-black/50 border ${errors.firstName ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
              />
              {errors.firstName && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.firstName}</span>}
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-300">{t.lastName} <span className="text-brand-gold">*</span></label>
              <input 
                type="text" 
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                className={`w-full bg-black/50 border ${errors.lastName ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
              />
              {errors.lastName && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.lastName}</span>}
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-300">{t.email} <span className="text-brand-gold">*</span></label>
            <input 
              type="email" 
              name="email"
              value={formData.email}
              onChange={handleChange}
              className={`w-full bg-black/50 border ${errors.email ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
            />
            {errors.email && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.email}</span>}
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-300">{t.phone} <span className="text-brand-gold">*</span></label>
            <div className={`flex bg-black/50 border ${errors.phone ? 'border-red-500' : 'border-white/10'} rounded-lg overflow-hidden transition focus-within:border-brand-gold`}>
               <div className="px-4 py-3 bg-white/5 border-r border-white/10 text-gray-400 select-none ltr:border-r rtl:border-l rtl:border-r-0">
                 +965
               </div>
               <input 
                  type="tel" 
                  name="phone"
                  value={formData.phone}
                  onChange={handleChange}
                  placeholder="xxxxxxxx"
                  maxLength={8}
                  className="w-full bg-transparent border-none px-4 py-3 text-white outline-none placeholder-gray-600"
                />
            </div>
            {errors.phone && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.phone}</span>}
          </div>

          {/* Company Specific Fields */}
          {role === 'company' && (
            <div className="space-y-6 pt-4 border-t border-white/10 animate-fade-in">
              <h3 className="text-brand-gold font-bold uppercase tracking-widest text-sm border-b border-white/10 pb-2">Project Overview (Summary)</h3>

              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">{t.companyName} <span className="text-brand-gold">*</span></label>
                <input 
                  type="text" 
                  name="companyName"
                  value={formData.companyName}
                  onChange={handleChange}
                  className={`w-full bg-black/50 border ${errors.companyName ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                />
                {errors.companyName && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.companyName}</span>}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div className="space-y-2">
                  <label className="text-sm font-medium text-gray-300">{t.sector} <span className="text-brand-gold">*</span></label>
                  <select 
                    name="sector"
                    value={formData.sector}
                    onChange={handleChange}
                    className={`w-full bg-black/50 border ${errors.sector ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                  >
                    <option value="">{lang === 'en' ? 'Select Sector' : 'اختر القطاع'}</option>
                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  {errors.sector && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.sector}</span>}
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-medium text-gray-300">{t.companyAge} <span className="text-brand-gold">*</span></label>
                  <input 
                    type="number" 
                    name="companyAge"
                    value={formData.companyAge}
                    onChange={handleChange}
                    className={`w-full bg-black/50 border ${errors.companyAge ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                  />
                  {errors.companyAge && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.companyAge}</span>}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-medium text-gray-300">{t.legalEntity} <span className="text-brand-gold">*</span></label>
                  <input 
                    type="text" 
                    name="legalEntity"
                    placeholder="e.g. LLC"
                    value={formData.legalEntity}
                    onChange={handleChange}
                    className={`w-full bg-black/50 border ${errors.legalEntity ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                  />
                  {errors.legalEntity && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.legalEntity}</span>}
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium text-gray-300">{t.companyType} <span className="text-brand-gold">*</span></label>
                  <input 
                    type="text" 
                    name="companyType"
                    placeholder="e.g. Startup, SME"
                    value={formData.companyType}
                    onChange={handleChange}
                    className={`w-full bg-black/50 border ${errors.companyType ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                  />
                  {errors.companyType && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.companyType}</span>}
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">{t.requestedInvestment} <span className="text-brand-gold">*</span></label>
                <input 
                  type="number" 
                  name="requestedInvestment"
                  value={formData.requestedInvestment}
                  onChange={handleChange}
                  className={`w-full bg-black/50 border ${errors.requestedInvestment ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                />
                {errors.requestedInvestment && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.requestedInvestment}</span>}
              </div>

              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">{t.investmentReason} <span className="text-brand-gold">*</span></label>
                <textarea 
                  name="investmentReason"
                  rows={3}
                  value={formData.investmentReason}
                  onChange={handleChange}
                  className={`w-full bg-black/50 border ${errors.investmentReason ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                />
                {errors.investmentReason && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.investmentReason}</span>}
              </div>

              <h3 className="text-brand-gold font-bold uppercase tracking-widest text-sm border-b border-white/10 pb-2 mt-8">Project File (Full Details)</h3>

              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">{t.shareToSell} <span className="text-brand-gold">*</span></label>
                <input 
                  type="number" 
                  name="shareToSell"
                  max="100"
                  value={formData.shareToSell}
                  onChange={handleChange}
                  className={`w-full bg-black/50 border ${errors.shareToSell ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                />
                {errors.shareToSell && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.shareToSell}</span>}
              </div>

              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">{t.fullDetails} <span className="text-brand-gold">*</span></label>
                <textarea 
                  name="fullDetails"
                  rows={5}
                  value={formData.fullDetails}
                  onChange={handleChange}
                  className={`w-full bg-black/50 border ${errors.fullDetails ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                />
                {errors.fullDetails && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.fullDetails}</span>}
              </div>

            </div>
          )}

          <div className="pt-6">
            <button 
              type="submit" 
              disabled={isSubmitting}
              className="w-full bg-brand-gold text-black font-bold text-lg py-4 rounded-xl hover:bg-yellow-500 transition shadow-lg shadow-brand-gold/20 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isSubmitting ? (
                 <span className="flex items-center justify-center gap-2">
                   <span className="w-5 h-5 border-2 border-black/30 border-t-black rounded-full animate-spin"></span>
                   {lang === 'en' ? 'Processing...' : 'جاري المعالجة...'}
                 </span>
              ) : t.createAccount}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

