import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, UserRole, Project, Language } from '../types';
import { SAMPLE_PROJECTS } from '../constants';

interface StoreContextType {
  user: User | null;
  lang: Language;
  projects: Project[];
  toggleLanguage: () => void;
  login: (role: UserRole, email?: string) => void;
  logout: () => void;
  unlockProject: (projectId: string) => void;
  isProjectUnlocked: (projectId: string) => boolean;
  requestInterest: (projectId: string) => void;
  toggleFavorite: (projectId: string) => void;
  isFavorite: (projectId: string) => boolean;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [lang, setLang] = useState<Language>('ar');
  const [user, setUser] = useState<User | null>(null);
  const [projects] = useState<Project[]>(SAMPLE_PROJECTS);

  // Layout direction effect
  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
  }, [lang]);

  const toggleLanguage = () => setLang(prev => prev === 'en' ? 'ar' : 'en');

  const login = (role: UserRole, email: string = 'user@bi-platform.com') => {
    // Mock login with random ID and provided email
    // If role is company, we simulate a license URL being present
    const licenseUrl = role === 'company' 
      ? 'https://images.unsplash.com/photo-1563986768609-322da13575f3?auto=format&fit=crop&w=400&q=80' // Mock Document Image
      : undefined;

    setUser({
      id: `USR-${Math.floor(Math.random() * 10000)}`,
      name: role === 'company' ? 'Business Owner' : 'Verified Investor',
      email: email,
      role: role,
      subscriptionPlan: role === 'investor' ? 'premium' : undefined,
      unlockedProjects: [],
      favorites: [],
      companyLicenseUrl: licenseUrl
    });
  };

  const logout = () => setUser(null);

  const unlockProject = (projectId: string) => {
    if (!user) return;
    if (user.unlockedProjects.includes(projectId)) return;

    // Simulate payment success
    setUser({ ...user, unlockedProjects: [...user.unlockedProjects, projectId] });
    alert(lang === 'en' ? 'Payment Successful. File Unlocked.' : 'تم الدفع بنجاح. تم فتح الملف.');
  };

  const isProjectUnlocked = (projectId: string) => {
    if (!user) return false;
    return user.unlockedProjects.includes(projectId);
  };

  const requestInterest = (projectId: string) => {
    alert(lang === 'en' ? 'Interest registered. Admin will contact you shortly.' : 'تم تسجيل اهتمامك. سيتصل بك المسؤول قريباً.');
  };

  const toggleFavorite = (projectId: string) => {
    if (!user) {
      alert(lang === 'en' ? 'Please login to save favorites.' : 'يرجى تسجيل الدخول لحفظ المفضلة.');
      return;
    }

    const isFav = user.favorites.includes(projectId);
    const newFavorites = isFav 
      ? user.favorites.filter(id => id !== projectId)
      : [...user.favorites, projectId];

    setUser({ ...user, favorites: newFavorites });
  };

  const isFavorite = (projectId: string) => {
    if (!user) return false;
    return user.favorites.includes(projectId);
  };

  return (
    <StoreContext.Provider value={{ 
      user, lang, projects, toggleLanguage, login, logout, unlockProject, isProjectUnlocked, requestInterest, toggleFavorite, isFavorite
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error("useStore must be used within StoreProvider");
  return context;
};

import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate, Link } from 'react-router-dom';
import { useStore } from '../context/Store';
import { TRANSLATIONS, CATEGORIES } from '../constants';
import { Briefcase, TrendingUp, CheckCircle, AlertCircle, Upload, FileText } from 'lucide-react';

export const Signup: React.FC = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { lang } = useStore();
  const t = TRANSLATIONS[lang].auth;

  // Default to investor if not specified
  const role = searchParams.get('role') === 'company' ? 'company' : 'investor';

  // Helper to get demo defaults based on role
  const getDefaults = (currentRole: string) => {
    if (currentRole === 'company') {
      return {
        firstName: 'محمد',
        lastName: 'العتيبي',
        email: 'company.test@bi.com',
        phone: '88880000',
        companyName: 'شركة المستقبل للاستثمار',
        companyAge: '5',
        sector: 'Technology & SaaS', 
        valuation: '250000',
        investorType: '',
        // Company Fields
        legalEntity: 'LLC',
        companyType: 'Startup',
        requestedInvestment: '50000',
        investmentReason: 'Expansion into GCC market',
        shareToSell: '20',
        fullDetails: 'Detailed breakdown of SaaS product roadmap, user acquisition strategy, and 5-year financial projections.',
        // Investor Fields (empty)
        investorSector: '',
        investorCapital: '',
        investmentCount: '',
        investorExperience: ''
      };
    }
    return {
      firstName: 'أحمد',
      lastName: 'الشمري',
      email: 'investor.test@bi.com',
      phone: '99990000',
      companyName: '',
      companyAge: '',
      sector: '',
      valuation: '',
      investorType: 'individual',
      // Reset company fields
      legalEntity: '',
      companyType: '',
      requestedInvestment: '',
      investmentReason: '',
      shareToSell: '',
      fullDetails: '',
      // Investor Fields
      investorSector: 'Real Estate',
      investorCapital: '100000',
      investmentCount: '3',
      investorExperience: 'intermediate'
    };
  };

  const [formData, setFormData] = useState(getDefaults(role));
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isOtherSector, setIsOtherSector] = useState(false);
  const [agreed, setAgreed] = useState(false);

  // File state
  const [licenseFile, setLicenseFile] = useState<File | null>(null);
  const [licensePreview, setLicensePreview] = useState<string | null>(null);

  useEffect(() => {
    // Reset form and errors when role changes
    setFormData(getDefaults(role));
    setErrors({});
    setIsOtherSector(false);
    setLicenseFile(null);
    setLicensePreview(null);
    setAgreed(false);
  }, [role]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    // For phone, only allow digits and max 8
    if (name === 'phone') {
      if (!/^\d*$/.test(value)) return;
      if (value.length > 8) return;
    }
    setFormData(prev => ({ ...prev, [name]: value }));
    // Clear error for field
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate size (10MB = 10 * 1024 * 1024)
    if (file.size > 10 * 1024 * 1024) {
        setErrors(prev => ({...prev, license: t.licenseErrorSize}));
        return;
    }
    // Validate type (Images and PDF)
    if (!['image/jpeg', 'image/png', 'image/jpg', 'application/pdf'].includes(file.type)) {
         setErrors(prev => ({...prev, license: t.licenseErrorType}));
         return;
    }

    setLicenseFile(file);
    if (file.type.startsWith('image/')) {
        setLicensePreview(URL.createObjectURL(file));
    } else {
        setLicensePreview(null); // No preview for PDF, just show icon/name
    }
    setErrors(prev => ({...prev, license: ''}));
  };

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!formData.firstName.trim()) newErrors.firstName = t.required;
    if (!formData.lastName.trim()) newErrors.lastName = t.required;
    if (!formData.email.trim()) {
      newErrors.email = t.required;
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = t.invalidEmail;
    }

    if (!formData.phone.trim()) {
      newErrors.phone = t.required;
    } else if (formData.phone.length !== 8) {
      newErrors.phone = t.invalidPhone;
    }

    if (role === 'company') {
      if (!formData.companyName.trim()) newErrors.companyName = t.required;
      if (!formData.companyAge.trim()) newErrors.companyAge = t.required;
      if (!formData.sector.trim()) newErrors.sector = t.required;
      if (!formData.legalEntity.trim()) newErrors.legalEntity = t.required;
      if (!formData.companyType.trim()) newErrors.companyType = t.required;
      if (!formData.requestedInvestment.trim()) newErrors.requestedInvestment = t.required;
      if (!formData.investmentReason.trim()) newErrors.investmentReason = t.required;
      if (!formData.shareToSell.trim()) newErrors.shareToSell = t.required;
      if (!formData.fullDetails.trim()) newErrors.fullDetails = t.required;
      if (!licenseFile) newErrors.license = t.required;
    }

    if (role === 'investor') {
       if (!formData.investorType) newErrors.investorType = t.required;
       if (!formData.investorSector.trim()) newErrors.investorSector = t.required;
       if (!formData.investorCapital.trim()) {
          newErrors.investorCapital = t.required;
       } else if (parseFloat(formData.investorCapital) <= 0) {
          newErrors.investorCapital = "Must be > 0";
       }
       if (!formData.investmentCount.trim()) {
          newErrors.investmentCount = t.required;
       } else if (parseInt(formData.investmentCount) < 0) {
          newErrors.investmentCount = "Cannot be negative";
       }
       if (!formData.investorExperience) newErrors.investorExperience = t.required;
    }

    if (!agreed) {
      newErrors.agreement = t.termsError;
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validate()) {
      setIsSubmitting(true);
      // Simulate API call
      setTimeout(() => {
        setIsSubmitting(false);
        navigate('/verify-email');
      }, 1500);
    }
  };

  const handleSectorChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value;
    if (val === 'Other') {
      setIsOtherSector(true);
      setFormData(prev => ({...prev, investorSector: ''}));
    } else {
      setIsOtherSector(false);
      setFormData(prev => ({...prev, investorSector: val}));
