                 <CheckCircle size={16} className="text-brand-gold" />
                 <span>{lang === 'en' ? 'Verified Ownership' : 'ملكية موثقة'}</span>
               </li>
               <li className="flex items-center gap-3 text-sm text-gray-400">
                 <CheckCircle size={16} className="text-brand-gold" />
                 <span>{lang === 'en' ? 'Audited Financials' : 'بيانات مالية مدققة'}</span>
               </li>
               <li className="flex items-center gap-3 text-sm text-gray-400">
                 <CheckCircle size={16} className="text-brand-gold" />
                 <span>{lang === 'en' ? 'Admin Escrow Available' : 'خدمة الضمان الإداري متاحة'}</span>
               </li>
             </ul>
          </div>
          <div className="p-4 bg-brand-gold/10 border border-brand-gold/20 rounded-xl">
             <p className="text-xs text-brand-gold text-center">
               {t.common.commission}
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

