        // Investor Fields (empty)
        investorSector: '',
        investorCapital: '',
        investmentCount: '',
        investorExperience: ''
      };
    }
    return {
      firstName: 'أحمد',
      lastName: 'الشمري',
      email: 'investor.test@bi.com',
      phone: '99990000',
      companyName: '',
      companyAge: '',
