      <div className="bg-brand-dark py-20 border-b border-white/10 relative overflow-hidden">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_top_right,_var(--tw-gradient-stops))] from-brand-gold/10 via-transparent to-transparent"></div>
        <div className="max-w-4xl mx-auto px-4 text-center relative z-10">
          <h1 className="text-4xl md:text-6xl font-bold mb-6 text-white">{t.title}</h1>
          <p className="text-xl text-gray-400 leading-relaxed max-w-2xl mx-auto">
            {t.intro}
          </p>
        </div>
      </div>

      {/* Content Sections */}
      <div className="max-w-7xl mx-auto px-4 py-16">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 lg:gap-12">
          {t.sections.map((section, index) => {
            const Icon = icons[index % icons.length];
            return (
              <div key={index} className="bg-brand-gray/30 border border-white/5 p-8 rounded-2xl hover:border-brand-gold/30 transition duration-300">
                <div className="w-12 h-12 bg-brand-gold/10 rounded-xl flex items-center justify-center text-brand-gold mb-6">
                  <Icon size={28} />
                </div>
                <h3 className="text-2xl font-bold text-white mb-4">{section.title}</h3>
                <p className="text-gray-400 leading-relaxed text-lg">
                  {section.body}
                </p>
              </div>
            );
          })}
        </div>

        {/* CTA Section */}
        <div className="mt-20 text-center">
          <Link 
            to="/projects" 
            className="inline-flex items-center gap-2 bg-brand-gold text-black px-10 py-4 rounded-full font-bold text-lg hover:bg-yellow-500 transition shadow-lg shadow-brand-gold/20"
          >
            {t.cta}
            {lang === 'ar' ? <ArrowLeft size={20} /> : <ArrowRight size={20} />}
          </Link>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { HashRouter, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { StoreProvider } from './context/Store';
import { Layout } from './components/Layout';
import { Home } from './pages/Home';
import { Projects } from './pages/Projects';
import { ProjectDetails } from './pages/ProjectDetails';
import { Pricing } from './pages/Pricing';
import { Dashboard } from './pages/Dashboard';
import { Login } from './pages/Login';
import { RegisterType } from './pages/RegisterType';
import { LoginType } from './pages/LoginType';
import { Signup } from './pages/Signup';
import { VerifyEmail } from './pages/VerifyEmail';
import { Favorites } from './pages/Favorites';
import { TermsOfUse } from './pages/TermsOfUse';
import { PrivacyPolicy } from './pages/PrivacyPolicy';
import { AddListing } from './pages/AddListing';
import { About } from './pages/About';

const ScrollToTop = () => {
  const { pathname } = useLocation();
  React.useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
}

// Wrapper to use router hooks inside ScrollToTop
const AppRoutes = () => {
  return (
    <>
      <ScrollToTop />
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/projects" element={<Projects />} />
        <Route path="/projects/:id" element={<ProjectDetails />} />
        <Route path="/pricing" element={<Pricing />} />
        <Route path="/dashboard" element={<Dashboard />} />
        <Route path="/favorites" element={<Favorites />} />
        <Route path="/login" element={<Login />} />
        <Route path="/login-type" element={<LoginType />} />
        <Route path="/register-type" element={<RegisterType />} />
        <Route path="/signup" element={<Signup />} />
        <Route path="/verify-email" element={<VerifyEmail />} />
        <Route path="/terms-of-use" element={<TermsOfUse />} />
        <Route path="/privacy-policy" element={<PrivacyPolicy />} />
        <Route path="/advertiser/new-listing" element={<AddListing />} />
        <Route path="/about" element={<About />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </>
  );
}

const App: React.FC = () => {
  return (
    <StoreProvider>
      <HashRouter>
        <Layout>
          <AppRoutes />
        </Layout>
      </HashRouter>
    </StoreProvider>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate, Link } from 'react-router-dom';
import { useStore } from '../context/Store';
import { TRANSLATIONS, CATEGORIES } from '../constants';
import { Briefcase, TrendingUp, CheckCircle, AlertCircle, Upload, FileText } from 'lucide-react';

export const Signup: React.FC = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { lang } = useStore();
  const t = TRANSLATIONS[lang].auth;

  // Default to investor if not specified. Handle legacy 'company' parameter.
  const roleParam = searchParams.get('role');
  const role = (roleParam === 'company' || roleParam === 'advertiser') ? 'advertiser' : 'investor';

  // Helper to get demo defaults based on role
  const getDefaults = (currentRole: string) => {
    if (currentRole === 'advertiser') {
      return {
        firstName: 'محمد',
        lastName: 'العتيبي',
        email: 'advertiser.test@bi.com',
        phone: '88880000',
        password: '',
        // Removed Project Fields - Now in AddListing.tsx
        // Investor Fields (empty)
        investorSector: '',
        investorCapital: '',
        investmentCount: '',
        investorExperience: ''
      };
    }
    return {
      firstName: 'أحمد',
      lastName: 'الشمري',
      email: 'investor.test@bi.com',
      phone: '99990000',
      password: '',
      investorType: 'angel', // Default to angel
      // Investor Fields
      investorSector: 'Real Estate',
      investorCapital: '100000',
      investmentCount: '3',
      investorExperience: 'intermediate'
    };
  };

  const [formData, setFormData] = useState(getDefaults(role));
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isOtherSector, setIsOtherSector] = useState(false);
  const [agreed, setAgreed] = useState(false);

  // File state
  const [licenseFile, setLicenseFile] = useState<File | null>(null);
  const [licensePreview, setLicensePreview] = useState<string | null>(null);

  useEffect(() => {
    // Reset form and errors when role changes
    setFormData(getDefaults(role));
    setErrors({});
    setIsOtherSector(false);
    setLicenseFile(null);
    setLicensePreview(null);
    setAgreed(false);
  }, [role]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    // For phone, only allow digits and max 8
    if (name === 'phone') {
      if (!/^\d*$/.test(value)) return;
      if (value.length > 8) return;
    }
    setFormData(prev => ({ ...prev, [name]: value }));
    // Clear error for field
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate size (10MB = 10 * 1024 * 1024)
    if (file.size > 10 * 1024 * 1024) {
        setErrors(prev => ({...prev, license: t.licenseErrorSize}));
        return;
    }
    // Validate type (Images and PDF)
    if (!['image/jpeg', 'image/png', 'image/jpg', 'application/pdf'].includes(file.type)) {
         setErrors(prev => ({...prev, license: t.licenseErrorType}));
         return;
    }

    setLicenseFile(file);
    if (file.type.startsWith('image/')) {
        setLicensePreview(URL.createObjectURL(file));
    } else {
        setLicensePreview(null); // No preview for PDF, just show icon/name
    }
    setErrors(prev => ({...prev, license: ''}));
  };

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!formData.firstName.trim()) newErrors.firstName = t.required;
    if (!formData.lastName.trim()) newErrors.lastName = t.required;
    if (!formData.email.trim()) {
      newErrors.email = t.required;
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = t.invalidEmail;
    }

    if (!formData.phone.trim()) {
      newErrors.phone = t.required;
    } else if (formData.phone.length !== 8) {
      newErrors.phone = t.invalidPhone;
    }

    if (role === 'advertiser') {
      // Advertiser is now simpler - Just identity verification (License)
      if (!licenseFile) newErrors.license = t.required;
    }

    if (role === 'investor') {
       if (!formData.investorType) newErrors.investorType = t.required;
       if (!formData.investorSector.trim()) newErrors.investorSector = t.required;
       if (!formData.investorCapital.trim()) {
          newErrors.investorCapital = t.required;
       } else if (parseFloat(formData.investorCapital) <= 0) {
          newErrors.investorCapital = "Must be > 0";
       }
       if (!formData.investmentCount.trim()) {
          newErrors.investmentCount = t.required;
       } else if (parseInt(formData.investmentCount) < 0) {
          newErrors.investmentCount = "Cannot be negative";
       }
       if (!formData.investorExperience) newErrors.investorExperience = t.required;
    }

    if (!agreed) {
      newErrors.agreement = t.termsError;
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validate()) {
      setIsSubmitting(true);
      // Simulate API call
      setTimeout(() => {
        setIsSubmitting(false);
        navigate('/verify-email');
      }, 1500);
    }
  };

  const handleSectorChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value;
    if (val === 'Other') {
      setIsOtherSector(true);
      setFormData(prev => ({...prev, investorSector: ''}));
    } else {
      setIsOtherSector(false);
      setFormData(prev => ({...prev, investorSector: val}));
    }
  };

  return (
    <div className="min-h-[85vh] flex items-center justify-center px-4 py-12">
      <div className="max-w-2xl w-full bg-brand-gray/20 border border-white/10 rounded-2xl p-8 backdrop-blur-sm animate-fade-in">

        {/* Header */}
        <div className="text-center mb-10">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-brand-gold/10 text-brand-gold mb-4">
             {role === 'advertiser' ? <Briefcase size={32} /> : <TrendingUp size={32} />}
          </div>
          <h2 className="text-3xl font-bold text-white mb-2">
            {role === 'advertiser' ? t.advertiser : t.investor}
          </h2>
          <p className="text-gray-400 max-w-md mx-auto">
            {role === 'advertiser' ? t.advertiserSubtitle : t.investorSubtitle}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">

          {/* Investor Type Segmented Control */}
          {role === 'investor' && (
            <div className="space-y-6 animate-fade-in">
               <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">{t.investorType} <span className="text-brand-gold">*</span></label>
                <div className="grid grid-cols-3 gap-2 bg-black/50 p-1 rounded-xl border border-white/10">
                  {['angel', 'company', 'crowdfunding'].map((type) => (
                    <button
                        key={type}
                        type="button"
                        onClick={() => setFormData(prev => ({ ...prev, investorType: type }))}
                        className={`py-3 rounded-lg text-xs md:text-sm font-bold transition-all duration-300 ${formData.investorType === type ? 'bg-brand-gold text-black shadow-lg shadow-brand-gold/20' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
                    >
                        {type === 'angel' ? t.angelType : type === 'company' ? t.companyType : t.crowdType}
                    </button>
                  ))}
                </div>

                {/* Description Panel */}
                <div className="bg-brand-gray/20 border border-white/5 rounded-xl p-4 mt-2 animate-fade-in">
                   <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-sm">
                      <div className="flex flex-col">
                         <span className="text-gray-500 text-xs mb-1 uppercase tracking-wider">{t.descCapital}</span>
                         <span className="font-bold text-white">{
                            formData.investorType === 'company' || formData.investorType === 'crowdfunding' ? t.valCap100 : t.valCap10
                         }</span>
                      </div>
                      <div className="flex flex-col">
                         <span className="text-gray-500 text-xs mb-1 uppercase tracking-wider">{t.descField}</span>
                         <span className="font-bold text-brand-gold">{
                            formData.investorType === 'company' ? t.valFieldTech :
                            formData.investorType === 'angel' ? t.valFieldTechFood :
                            t.valFieldRE
                         }</span>
                      </div>
                      <div className="flex flex-col">
                         <span className="text-gray-500 text-xs mb-1 uppercase tracking-wider">{t.descExp}</span>
                         <span className="font-bold text-white">{
                            formData.investorType === 'company' ? t.valExp7 :
                            formData.investorType === 'angel' ? t.valExp2 :
                            t.valExp4
                         }</span>
                      </div>
                   </div>
                </div>
              </div>
            </div>
          )}

          {/* Common Fields - Personal Info */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-300">{t.firstName} <span className="text-brand-gold">*</span></label>
              <input 
                type="text" 
                name="firstName" 
                value={formData.firstName}
                onChange={handleChange}
                className={`w-full bg-black/50 border ${errors.firstName ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
              />
              {errors.firstName && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.firstName}</span>}
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-300">{t.lastName} <span className="text-brand-gold">*</span></label>
              <input 
                type="text" 
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                className={`w-full bg-black/50 border ${errors.lastName ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
              />
              {errors.lastName && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.lastName}</span>}
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-300">{t.email} <span className="text-brand-gold">*</span></label>
            <input 
              type="email" 
              name="email"
              value={formData.email}
              onChange={handleChange}
              className={`w-full bg-black/50 border ${errors.email ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
            />
            {errors.email && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.email}</span>}
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-300">{t.phone} <span className="text-brand-gold">*</span></label>
            <div className={`flex bg-black/50 border ${errors.phone ? 'border-red-500' : 'border-white/10'} rounded-lg overflow-hidden transition focus-within:border-brand-gold`}>
               <div className="px-4 py-3 bg-white/5 border-r border-white/10 text-gray-400 select-none ltr:border-r rtl:border-l rtl:border-r-0">
                 +965
               </div>
               <input 
                  type="tel" 
                  name="phone"
                  value={formData.phone}
                  onChange={handleChange}
                  placeholder="xxxxxxxx"
                  maxLength={8}
                  className="w-full bg-transparent border-none px-4 py-3 text-white outline-none placeholder-gray-600"
                />
            </div>
            {errors.phone && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.phone}</span>}
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-300">{t.password} <span className="text-brand-gold">*</span></label>
            <input 
              type="password" 
              name="password"
              value={formData.password}
              onChange={handleChange}
              className={`w-full bg-black/50 border ${errors.password ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
            />
          </div>

          {/* New Investor Specific Fields */}
          {role === 'investor' && (
            <div className="space-y-6 pt-4 border-t border-white/10 animate-fade-in">
              <h3 className="text-brand-gold font-bold uppercase tracking-widest text-sm border-b border-white/10 pb-2">Investor Profile</h3>

              {/* Sector */}
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">{t.investorSector} <span className="text-brand-gold">*</span></label>
                <select 
                  onChange={handleSectorChange}
                  value={isOtherSector ? 'Other' : formData.investorSector}
                  className={`w-full bg-black/50 border ${errors.investorSector ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                >
                  <option value="">{lang === 'en' ? 'Select Sector' : 'اختر المجال'}</option>
                  {CATEGORIES.map(c => <option key={c.en} value={c.en}>{c[lang]}</option>)}
                  <option value="Other">{t.other}</option>
                </select>
                {isOtherSector && (
                  <input 
                    type="text"
                    name="investorSector"
                    placeholder={t.other}
                    value={formData.investorSector}
                    onChange={handleChange}
                    className="w-full mt-2 bg-black/50 border border-brand-gold rounded-lg px-4 py-3 text-white focus:outline-none"
                  />
                )}
                {errors.investorSector && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.investorSector}</span>}
              </div>

              {/* Capital & Count */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-medium text-gray-300">{t.investorCapital} <span className="text-brand-gold">*</span></label>
                  <input 
                    type="number" 
                    name="investorCapital"
                    value={formData.investorCapital}
                    onChange={handleChange}
                    min="0"
                    className={`w-full bg-black/50 border ${errors.investorCapital ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                  />
                  {errors.investorCapital && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.investorCapital}</span>}
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium text-gray-300">{t.investmentCount} <span className="text-brand-gold">*</span></label>
                  <input 
                    type="number" 
                    name="investmentCount"
                    value={formData.investmentCount}
                    onChange={handleChange}
                    min="0"
                    className={`w-full bg-black/50 border ${errors.investmentCount ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                  />
                  {errors.investmentCount && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.investmentCount}</span>}
                </div>
              </div>

              {/* Experience Segmented */}
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">{t.investorExperience} <span className="text-brand-gold">*</span></label>
                <div className="flex bg-black/50 p-1 rounded-xl border border-white/10">
                  <button
                    type="button"
                    onClick={() => setFormData(prev => ({ ...prev, investorExperience: 'beginner' }))}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all duration-300 ${formData.investorExperience === 'beginner' ? 'bg-brand-gold text-black shadow-lg shadow-brand-gold/20' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
                  >
                    {t.expBeginner}
                  </button>
                  <button
                    type="button"
                    onClick={() => setFormData(prev => ({ ...prev, investorExperience: 'intermediate' }))}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all duration-300 ${formData.investorExperience === 'intermediate' ? 'bg-brand-gold text-black shadow-lg shadow-brand-gold/20' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
                  >
                    {t.expIntermediate}
                  </button>
                  <button
                    type="button"
                    onClick={() => setFormData(prev => ({ ...prev, investorExperience: 'expert' }))}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all duration-300 ${formData.investorExperience === 'expert' ? 'bg-brand-gold text-black shadow-lg shadow-brand-gold/20' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
                  >
                    {t.expExpert}
                  </button>
                </div>
                {errors.investorExperience && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.investorExperience}</span>}
              </div>
            </div>
          )}

          {/* Advertiser Specific Fields - Only License Verification */}
          {role === 'advertiser' && (
            <div className="space-y-6 pt-4 border-t border-white/10 animate-fade-in">
              <h3 className="text-brand-gold font-bold uppercase tracking-widest text-sm border-b border-white/10 pb-2">Business Verification</h3>

              {/* License Upload Field */}
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">{t.companyLicense} <span className="text-brand-gold">*</span></label>
                <div className={`relative w-full border-2 border-dashed ${errors.license ? 'border-red-500' : 'border-white/10'} rounded-lg p-6 flex flex-col items-center justify-center text-center hover:border-brand-gold/50 transition bg-black/30 group cursor-pointer`}>
                   <input 
                      type="file" 
                      accept=".jpg,.jpeg,.png,.pdf"
                      onChange={handleFileChange}
                      className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                   />

                   {licenseFile ? (
                      <div className="flex flex-col items-center">
                         {licensePreview ? (
                            <img src={licensePreview} alt="Preview" className="h-32 object-contain mb-3 rounded border border-white/20" />
                         ) : (
                            <FileText size={48} className="text-gray-400 mb-3" />
                         )}
                         <span className="text-brand-gold font-bold text-sm truncate max-w-[200px]">{licenseFile.name}</span>
                         <span className="text-xs text-gray-500 mt-1">{(licenseFile.size / 1024 / 1024).toFixed(2)} MB</span>
                         <span className="text-xs text-white/50 mt-2 bg-black/50 px-2 py-1 rounded">{t.replaceLicense}</span>
                      </div>
                   ) : (
                      <>
                         <Upload size={32} className="text-gray-400 mb-3 group-hover:text-brand-gold transition" />
                         <span className="text-sm text-gray-300 font-medium">{t.uploadLicense}</span>
                         <span className="text-xs text-gray-500 mt-1">MAX 10MB (JPG, PNG, PDF)</span>
                      </>
                   )}
                </div>
                {errors.license && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.license}</span>}
              </div>
            </div>
          )}

          {/* Terms & Conditions Consent */}
          <div className="pt-4 border-t border-white/10">
             <div className="flex items-start gap-3">
               <div className="relative flex items-center">
                 <input 
                   type="checkbox" 
                   id="termsAgreement"
                   checked={agreed}
                   onChange={(e) => {
                     setAgreed(e.target.checked);
                     if(e.target.checked && errors.agreement) {
                       setErrors(prev => ({...prev, agreement: ''}));
                     }
                   }}
                   className="peer h-5 w-5 cursor-pointer appearance-none rounded border border-white/30 bg-black/30 checked:border-brand-gold checked:bg-brand-gold transition-all"
                 />
                 <CheckCircle size={14} className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 text-black opacity-0 peer-checked:opacity-100 transition-opacity" />
               </div>
               <label htmlFor="termsAgreement" className="text-sm text-gray-300 cursor-pointer select-none leading-tight">
                 {t.agreeToTerms}
                 <Link to="/terms-of-use" target="_blank" rel="noopener noreferrer" className="text-brand-gold hover:underline">{t.termsOfUse}</Link>
                 {t.and}
                 <Link to="/privacy-policy" target="_blank" rel="noopener noreferrer" className="text-brand-gold hover:underline">{t.privacyPolicy}</Link>
               </label>
             </div>
             {errors.agreement && <span className="text-xs text-red-500 flex items-center gap-1 mt-2 animate-pulse"><AlertCircle size={12} /> {errors.agreement}</span>}
          </div>

          <div className="pt-2">
            <button 
              type="submit" 
              disabled={isSubmitting}
              className="w-full bg-brand-gold text-black font-bold text-lg py-4 rounded-xl hover:bg-yellow-500 transition shadow-lg shadow-brand-gold/20 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isSubmitting ? (
                 <span className="flex items-center justify-center gap-2">
                   <span className="w-5 h-5 border-2 border-black/30 border-t-black rounded-full animate-spin"></span>
                   {lang === 'en' ? 'Processing...' : 'جاري المعالجة...'}
                 </span>
              ) : t.createAccount}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate, Link } from 'react-router-dom';
import { useStore } from '../context/Store';
import { TRANSLATIONS, CATEGORIES } from '../constants';
import { Briefcase, TrendingUp, CheckCircle, AlertCircle, Upload, FileText } from 'lucide-react';

export const Signup: React.FC = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { lang } = useStore();
  const t = TRANSLATIONS[lang].auth;

  // Default to investor if not specified. Handle legacy 'company' parameter.
  const roleParam = searchParams.get('role');
  const role = (roleParam === 'company' || roleParam === 'advertiser') ? 'advertiser' : 'investor';

  // Helper to get demo defaults based on role
  const getDefaults = (currentRole: string) => {
    if (currentRole === 'advertiser') {
      return {
        firstName: 'محمد',
        lastName: 'العتيبي',
        email: 'advertiser.test@bi.com',
        phone: '88880000',
        password: '',
        // Removed Project Fields - Now in AddListing.tsx
        // Investor Fields (empty)
        investorSector: '',
        investorCapital: '',
        investmentCount: '',
        investorExperience: ''
      };
    }
    return {
      firstName: 'أحمد',
      lastName: 'الشمري',
      email: 'investor.test@bi.com',
      phone: '99990000',
      password: '',
      investorType: 'angel', // Default to angel
      // Investor Fields
      investorSector: 'Real Estate',
      investorCapital: '100000',
      investmentCount: '3',
      investorExperience: 'intermediate'
    };
  };

  const [formData, setFormData] = useState(getDefaults(role));
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isOtherSector, setIsOtherSector] = useState(false);
  const [agreed, setAgreed] = useState(false);

  // File state
  const [licenseFile, setLicenseFile] = useState<File | null>(null);
  const [licensePreview, setLicensePreview] = useState<string | null>(null);

  useEffect(() => {
    // Reset form and errors when role changes
    setFormData(getDefaults(role));
    setErrors({});
    setIsOtherSector(false);
    setLicenseFile(null);
    setLicensePreview(null);
    setAgreed(false);
  }, [role]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    // For phone, only allow digits and max 8
    if (name === 'phone') {
      if (!/^\d*$/.test(value)) return;
      if (value.length > 8) return;
    }
    setFormData(prev => ({ ...prev, [name]: value }));
    // Clear error for field
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate size (10MB = 10 * 1024 * 1024)
    if (file.size > 10 * 1024 * 1024) {
        setErrors(prev => ({...prev, license: t.licenseErrorSize}));
        return;
    }
    // Validate type (Images and PDF)
    if (!['image/jpeg', 'image/png', 'image/jpg', 'application/pdf'].includes(file.type)) {
         setErrors(prev => ({...prev, license: t.licenseErrorType}));
         return;
    }

    setLicenseFile(file);
    if (file.type.startsWith('image/')) {
        setLicensePreview(URL.createObjectURL(file));
    } else {
        setLicensePreview(null); // No preview for PDF, just show icon/name
    }
    setErrors(prev => ({...prev, license: ''}));
  };

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!formData.firstName.trim()) newErrors.firstName = t.required;
    if (!formData.lastName.trim()) newErrors.lastName = t.required;
    if (!formData.email.trim()) {
      newErrors.email = t.required;
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = t.invalidEmail;
    }

    if (!formData.phone.trim()) {
      newErrors.phone = t.required;
    } else if (formData.phone.length !== 8) {
      newErrors.phone = t.invalidPhone;
    }

    if (role === 'advertiser') {
      // Advertiser is now simpler - Just identity verification (License)
      if (!licenseFile) newErrors.license = t.required;
    }

    if (role === 'investor') {
       if (!formData.investorType) newErrors.investorType = t.required;
       if (!formData.investorSector.trim()) newErrors.investorSector = t.required;
       if (!formData.investorCapital.trim()) {
          newErrors.investorCapital = t.required;
       } else if (parseFloat(formData.investorCapital) <= 0) {
          newErrors.investorCapital = "Must be > 0";
       }
       if (!formData.investmentCount.trim()) {
          newErrors.investmentCount = t.required;
       } else if (parseInt(formData.investmentCount) < 0) {
          newErrors.investmentCount = "Cannot be negative";
       }
       if (!formData.investorExperience) newErrors.investorExperience = t.required;
    }

    if (!agreed) {
      newErrors.agreement = t.termsError;
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validate()) {
      setIsSubmitting(true);
      // Simulate API call
      setTimeout(() => {
        setIsSubmitting(false);
        navigate('/verify-email');
      }, 1500);
    }
  };

  const handleSectorChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value;
    if (val === 'Other') {
      setIsOtherSector(true);
      setFormData(prev => ({...prev, investorSector: ''}));
    } else {
      setIsOtherSector(false);
      setFormData(prev => ({...prev, investorSector: val}));
    }
  };

  return (
    <div className="min-h-[85vh] flex items-center justify-center px-4 py-12">
      <div className="max-w-2xl w-full bg-brand-gray/20 border border-white/10 rounded-2xl p-8 backdrop-blur-sm animate-fade-in">

        {/* Header */}
        <div className="text-center mb-10">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-brand-gold/10 text-brand-gold mb-4">
             {role === 'advertiser' ? <Briefcase size={32} /> : <TrendingUp size={32} />}
          </div>
          <h2 className="text-3xl font-bold text-white mb-2">
            {role === 'advertiser' ? t.advertiser : t.investor}
          </h2>
          <p className="text-gray-400 max-w-md mx-auto">
            {role === 'advertiser' ? t.advertiserSubtitle : t.investorSubtitle}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">

          {/* Investor Type Segmented Control */}
          {role === 'investor' && (
            <div className="space-y-6 animate-fade-in">
               <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">{t.investorType} <span className="text-brand-gold">*</span></label>
                <div className="grid grid-cols-3 gap-2 bg-black/50 p-1 rounded-xl border border-white/10">
                  {['angel', 'company', 'crowdfunding'].map((type) => {
                    const isSelected = formData.investorType === type;
                    return (
                    <button
                        key={type}
                        type="button"
                        onClick={() => setFormData(prev => ({ ...prev, investorType: type }))}
                        className={`relative py-3 rounded-lg text-xs md:text-sm font-bold transition-all duration-300 ${isSelected ? 'bg-brand-gold text-black shadow-lg shadow-brand-gold/20' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
                    >
                        {type === 'angel' ? t.angelType : type === 'company' ? t.companyType : t.crowdType}
                        {isSelected && (
                           <div className="absolute top-full left-1/2 -translate-x-1/2 w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[6px] border-t-brand-gold translate-y-1 z-10"></div>
                        )}
                    </button>
                    )
                  })}
                </div>

                {/* Description Panel */}
                <div className="bg-brand-gray/20 border border-white/10 rounded-xl p-6 mt-4 relative animate-fade-in">

                   {/* Heading */}
                   <h3 className="text-brand-gold font-bold text-sm uppercase tracking-wider mb-4 border-b border-white/10 pb-3">
                      {t.selectedTypeDetails.replace('{TYPE}', 
                        formData.investorType === 'angel' ? t.angelType : 
                        formData.investorType === 'company' ? t.companyType : t.crowdType
                      )}
                   </h3>

                   <div className="space-y-3">
                      <div className="flex items-center justify-between p-3 bg-black/20 rounded-lg border border-white/5">
                         <span className="text-gray-400 text-sm">{t.descCapital}</span>
                         <span className="font-bold text-white text-sm">
                            {formData.investorType === 'company' || formData.investorType === 'crowdfunding' ? t.valCap100 : t.valCap10}
                         </span>
                      </div>
                      <div className="flex items-center justify-between p-3 bg-black/20 rounded-lg border border-white/5">
                         <span className="text-gray-400 text-sm">{t.descField}</span>
                         <span className="font-bold text-white text-sm">
                             {formData.investorType === 'company' ? t.valFieldTech :
                              formData.investorType === 'angel' ? t.valFieldTechFood :
                              t.valFieldRE}
                         </span>
                      </div>
                      <div className="flex items-center justify-between p-3 bg-black/20 rounded-lg border border-white/5">
                         <span className="text-gray-400 text-sm">{t.descExp}</span>
                         <span className="font-bold text-white text-sm">
                             {formData.investorType === 'company' ? t.valExp7 :
                              formData.investorType === 'angel' ? t.valExp2 :
                              t.valExp4}
                         </span>
                      </div>
                   </div>
                </div>
              </div>
            </div>
          )}

          {/* Common Fields - Personal Info */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-300">{t.firstName} <span className="text-brand-gold">*</span></label>
              <input 
                type="text" 
                name="firstName" 
                value={formData.firstName}
                onChange={handleChange}
                className={`w-full bg-black/50 border ${errors.firstName ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
              />
              {errors.firstName && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.firstName}</span>}
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-300">{t.lastName} <span className="text-brand-gold">*</span></label>
              <input 
                type="text" 
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                className={`w-full bg-black/50 border ${errors.lastName ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
              />
              {errors.lastName && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.lastName}</span>}
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-300">{t.email} <span className="text-brand-gold">*</span></label>
            <input 
              type="email" 
              name="email"
              value={formData.email}
              onChange={handleChange}
              className={`w-full bg-black/50 border ${errors.email ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
            />
            {errors.email && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.email}</span>}
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-300">{t.phone} <span className="text-brand-gold">*</span></label>
            <div className={`flex bg-black/50 border ${errors.phone ? 'border-red-500' : 'border-white/10'} rounded-lg overflow-hidden transition focus-within:border-brand-gold`}>
               <div className="px-4 py-3 bg-white/5 border-r border-white/10 text-gray-400 select-none ltr:border-r rtl:border-l rtl:border-r-0">
                 +965
               </div>
               <input 
                  type="tel" 
                  name="phone"
                  value={formData.phone}
                  onChange={handleChange}
                  placeholder="xxxxxxxx"
                  maxLength={8}
                  className="w-full bg-transparent border-none px-4 py-3 text-white outline-none placeholder-gray-600"
                />
            </div>
            {errors.phone && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.phone}</span>}
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-300">{t.password} <span className="text-brand-gold">*</span></label>
            <input 
              type="password" 
              name="password"
              value={formData.password}
              onChange={handleChange}
              className={`w-full bg-black/50 border ${errors.password ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
            />
          </div>

          {/* New Investor Specific Fields */}
          {role === 'investor' && (
            <div className="space-y-6 pt-4 border-t border-white/10 animate-fade-in">
              <h3 className="text-brand-gold font-bold uppercase tracking-widest text-sm border-b border-white/10 pb-2">Investor Profile</h3>

              {/* Sector */}
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">{t.investorSector} <span className="text-brand-gold">*</span></label>
                <select 
                  onChange={handleSectorChange}
                  value={isOtherSector ? 'Other' : formData.investorSector}
                  className={`w-full bg-black/50 border ${errors.investorSector ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                >
                  <option value="">{lang === 'en' ? 'Select Sector' : 'اختر المجال'}</option>
                  {CATEGORIES.map(c => <option key={c.en} value={c.en}>{c[lang]}</option>)}
                  <option value="Other">{t.other}</option>
                </select>
                {isOtherSector && (
                  <input 
                    type="text"
                    name="investorSector"
                    placeholder={t.other}
                    value={formData.investorSector}
                    onChange={handleChange}
                    className="w-full mt-2 bg-black/50 border border-brand-gold rounded-lg px-4 py-3 text-white focus:outline-none"
                  />
                )}
                {errors.investorSector && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.investorSector}</span>}
              </div>

              {/* Capital & Count */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-medium text-gray-300">{t.investorCapital} <span className="text-brand-gold">*</span></label>
                  <input 
                    type="number" 
                    name="investorCapital"
                    value={formData.investorCapital}
                    onChange={handleChange}
                    min="0"
                    className={`w-full bg-black/50 border ${errors.investorCapital ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                  />
                  {errors.investorCapital && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.investorCapital}</span>}
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium text-gray-300">{t.investmentCount} <span className="text-brand-gold">*</span></label>
                  <input 
                    type="number" 
                    name="investmentCount"
                    value={formData.investmentCount}
                    onChange={handleChange}
                    min="0"
                    className={`w-full bg-black/50 border ${errors.investmentCount ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                  />
                  {errors.investmentCount && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.investmentCount}</span>}
                </div>
              </div>

              {/* Experience Segmented */}
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">{t.investorExperience} <span className="text-brand-gold">*</span></label>
                <div className="flex bg-black/50 p-1 rounded-xl border border-white/10">
                  <button
                    type="button"
                    onClick={() => setFormData(prev => ({ ...prev, investorExperience: 'beginner' }))}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all duration-300 ${formData.investorExperience === 'beginner' ? 'bg-brand-gold text-black shadow-lg shadow-brand-gold/20' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
                  >
                    {t.expBeginner}
                  </button>
                  <button
                    type="button"
                    onClick={() => setFormData(prev => ({ ...prev, investorExperience: 'intermediate' }))}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all duration-300 ${formData.investorExperience === 'intermediate' ? 'bg-brand-gold text-black shadow-lg shadow-brand-gold/20' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
                  >
                    {t.expIntermediate}
                  </button>
                  <button
                    type="button"
                    onClick={() => setFormData(prev => ({ ...prev, investorExperience: 'expert' }))}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all duration-300 ${formData.investorExperience === 'expert' ? 'bg-brand-gold text-black shadow-lg shadow-brand-gold/20' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
                  >
                    {t.expExpert}
                  </button>
                </div>
                {errors.investorExperience && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.investorExperience}</span>}
              </div>
            </div>
          )}

          {/* Advertiser Specific Fields - Only License Verification */}
          {role === 'advertiser' && (
            <div className="space-y-6 pt-4 border-t border-white/10 animate-fade-in">
              <h3 className="text-brand-gold font-bold uppercase tracking-widest text-sm border-b border-white/10 pb-2">Business Verification</h3>

              {/* License Upload Field */}
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">{t.companyLicense} <span className="text-brand-gold">*</span></label>
                <div className={`relative w-full border-2 border-dashed ${errors.license ? 'border-red-500' : 'border-white/10'} rounded-lg p-6 flex flex-col items-center justify-center text-center hover:border-brand-gold/50 transition bg-black/30 group cursor-pointer`}>
                   <input 
                      type="file" 
                      accept=".jpg,.jpeg,.png,.pdf"
                      onChange={handleFileChange}
                      className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                   />

                   {licenseFile ? (
                      <div className="flex flex-col items-center">
                         {licensePreview ? (
                            <img src={licensePreview} alt="Preview" className="h-32 object-contain mb-3 rounded border border-white/20" />
                         ) : (
                            <FileText size={48} className="text-gray-400 mb-3" />
                         )}
                         <span className="text-brand-gold font-bold text-sm truncate max-w-[200px]">{licenseFile.name}</span>
                         <span className="text-xs text-gray-500 mt-1">{(licenseFile.size / 1024 / 1024).toFixed(2)} MB</span>
                         <span className="text-xs text-white/50 mt-2 bg-black/50 px-2 py-1 rounded">{t.replaceLicense}</span>
                      </div>
                   ) : (
                      <>
                         <Upload size={32} className="text-gray-400 mb-3 group-hover:text-brand-gold transition" />
                         <span className="text-sm text-gray-300 font-medium">{t.uploadLicense}</span>
                         <span className="text-xs text-gray-500 mt-1">MAX 10MB (JPG, PNG, PDF)</span>
                      </>
                   )}
                </div>
                {errors.license && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.license}</span>}
              </div>
            </div>
          )}

          {/* Terms & Conditions Consent */}
          <div className="pt-4 border-t border-white/10">
             <div className="flex items-start gap-3">
               <div className="relative flex items-center">
                 <input 
                   type="checkbox" 
                   id="termsAgreement"
                   checked={agreed}
                   onChange={(e) => {
                     setAgreed(e.target.checked);
                     if(e.target.checked && errors.agreement) {
                       setErrors(prev => ({...prev, agreement: ''}));
                     }
                   }}
                   className="peer h-5 w-5 cursor-pointer appearance-none rounded border border-white/30 bg-black/30 checked:border-brand-gold checked:bg-brand-gold transition-all"
                 />
                 <CheckCircle size={14} className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 text-black opacity-0 peer-checked:opacity-100 transition-opacity" />
               </div>
               <label htmlFor="termsAgreement" className="text-sm text-gray-300 cursor-pointer select-none leading-tight">
                 {t.agreeToTerms}
                 <Link to="/terms-of-use" target="_blank" rel="noopener noreferrer" className="text-brand-gold hover:underline">{t.termsOfUse}</Link>
                 {t.and}
                 <Link to="/privacy-policy" target="_blank" rel="noopener noreferrer" className="text-brand-gold hover:underline">{t.privacyPolicy}</Link>
               </label>
             </div>
             {errors.agreement && <span className="text-xs text-red-500 flex items-center gap-1 mt-2 animate-pulse"><AlertCircle size={12} /> {errors.agreement}</span>}
          </div>

          <div className="pt-2">
            <button 
              type="submit" 
              disabled={isSubmitting}
              className="w-full bg-brand-gold text-black font-bold text-lg py-4 rounded-xl hover:bg-yellow-500 transition shadow-lg shadow-brand-gold/20 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isSubmitting ? (
                 <span className="flex items-center justify-center gap-2">
                   <span className="w-5 h-5 border-2 border-black/30 border-t-black rounded-full animate-spin"></span>
                   {lang === 'en' ? 'Processing...' : 'جاري المعالجة...'}
                 </span>
              ) : t.createAccount}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useStore } from '../context/Store';
import { Navigate, useNavigate } from 'react-router-dom';
import { TRANSLATIONS, CATEGORIES, COMPANY_STAGES } from '../constants';
import { ArrowLeft, ArrowRight, TrendingUp, Store, Info, CheckCircle, AlertCircle } from 'lucide-react';
import { ListingPurpose } from '../types';

export const AddListing: React.FC = () => {
  const { user, lang, addProject } = useStore();
  const navigate = useNavigate();
  const t = TRANSLATIONS[lang];

  const [step, setStep] = useState(1);
  const [purpose, setPurpose] = useState<ListingPurpose>('investment');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Form State
  const [formData, setFormData] = useState({
    companyName: '',
    sector: '',
    companyAge: '',
    legalEntity: '',
    companyType: '',
    companyStage: 'seed',
    requestedInvestment: '', // Reused for Sales Price based on context
    investmentReason: '',
    shareToSell: '',
    fullDetails: ''
  });

  if (!user || user.role !== 'advertiser') return <Navigate to="/dashboard" />;

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: '' }));
  };

  const validateStep2 = () => {
    const newErrors: Record<string, string> = {};
    if (!formData.companyName.trim()) newErrors.companyName = t.auth.required;
    if (!formData.sector.trim()) newErrors.sector = t.auth.required;
    if (!formData.companyAge.trim()) newErrors.companyAge = t.auth.required;
    if (!formData.legalEntity.trim()) newErrors.legalEntity = t.auth.required;
    if (!formData.companyType.trim()) newErrors.companyType = t.auth.required;
    if (!formData.requestedInvestment.trim()) newErrors.requestedInvestment = t.auth.required;
    // Share percentage is only required for investment listings
    if (purpose === 'investment' && !formData.shareToSell.trim()) {
        newErrors.shareToSell = t.auth.required;
    }
    if (!formData.fullDetails.trim()) newErrors.fullDetails = t.auth.required;
    if (!formData.investmentReason.trim()) newErrors.investmentReason = t.auth.required;

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validateStep2()) {
      setIsSubmitting(true);

      // Construct Project Object
      // In a real app, this would be an API call
      setTimeout(() => {
        addProject({
            listingPurpose: purpose,
            name: { ar: formData.companyName, en: formData.companyName },
            category: { ar: CATEGORIES.find(c => c.en === formData.sector)?.ar || 'عام', en: formData.sector },
            askingPrice: parseFloat(formData.requestedInvestment),
            age: { ar: `${formData.companyAge} سنوات`, en: `${formData.companyAge} Years` },
            shareOffered: purpose === 'sale' ? 100 : parseFloat(formData.shareToSell),
            legalEntity: { ar: formData.legalEntity, en: formData.legalEntity },
            companyType: { ar: formData.companyType, en: formData.companyType },
            companyStage: { 
                ar: COMPANY_STAGES.find(s => s.id === formData.companyStage)?.label.ar || '', 
                en: COMPANY_STAGES.find(s => s.id === formData.companyStage)?.label.en || '' 
            },
            investmentReason: { ar: formData.investmentReason, en: formData.investmentReason },
            descriptionShort: { ar: formData.investmentReason.substring(0, 100) + '...', en: formData.investmentReason.substring(0, 100) + '...' },
            descriptionFull: { ar: formData.fullDetails, en: formData.fullDetails }
        });

        setIsSubmitting(false);
        alert(t.listing.success);
        navigate('/dashboard');
      }, 1500);
    }
  };

  const selectedStageData = COMPANY_STAGES.find(s => s.id === formData.companyStage);

  return (
    <div className="max-w-3xl mx-auto px-4 py-12">

      {/* Progress */}
      <div className="flex items-center justify-between mb-8">
         <h1 className="text-2xl font-bold">{t.listing.title}</h1>
         <div className="flex items-center gap-2 text-sm text-gray-400">
            <span className={step === 1 ? 'text-brand-gold font-bold' : ''}>1. {t.listing.step1}</span>
            <span>&rarr;</span>
            <span className={step === 2 ? 'text-brand-gold font-bold' : ''}>2. {t.listing.step2}</span>
         </div>
      </div>

      <div className="bg-brand-gray/20 border border-white/10 rounded-2xl p-8 backdrop-blur-sm animate-fade-in">

        {step === 1 && (
            <div className="space-y-6">
                <h2 className="text-xl font-bold text-center mb-6">{t.listing.purposeTitle}</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <button 
                        onClick={() => setPurpose('investment')}
                        className={`p-6 rounded-xl border text-left transition-all group ${purpose === 'investment' ? 'bg-brand-gold text-black border-brand-gold' : 'bg-black/40 border-white/10 hover:border-brand-gold/50'}`}
                    >
                        <TrendingUp size={32} className={`mb-4 ${purpose === 'investment' ? 'text-black' : 'text-brand-gold'}`} />
                        <h3 className="font-bold text-lg mb-1">{t.listing.investment}</h3>
                        <p className={`text-sm ${purpose === 'investment' ? 'text-black/70' : 'text-gray-400'}`}>{t.listing.investmentDesc}</p>
                    </button>

                    <button 
                        onClick={() => setPurpose('sale')}
                        className={`p-6 rounded-xl border text-left transition-all group ${purpose === 'sale' ? 'bg-brand-gold text-black border-brand-gold' : 'bg-black/40 border-white/10 hover:border-brand-gold/50'}`}
                    >
                        <Store size={32} className={`mb-4 ${purpose === 'sale' ? 'text-black' : 'text-brand-gold'}`} />
                        <h3 className="font-bold text-lg mb-1">{t.listing.sale}</h3>
                        <p className={`text-sm ${purpose === 'sale' ? 'text-black/70' : 'text-gray-400'}`}>{t.listing.saleDesc}</p>
                    </button>
                </div>

                <div className="flex justify-end pt-6">
                    <button onClick={() => setStep(2)} className="bg-white text-black px-8 py-3 rounded-lg font-bold hover:bg-gray-200 transition flex items-center gap-2">
                        {t.listing.next} {lang === 'ar' ? <ArrowLeft size={18} /> : <ArrowRight size={18} />}
                    </button>
                </div>
            </div>
        )}

        {step === 2 && (
            <form onSubmit={handleSubmit} className="space-y-6 animate-fade-in">

                {/* Basic Info */}
                <div className="space-y-2">
                    <label className="text-sm font-medium text-gray-300">{t.auth.companyName} <span className="text-brand-gold">*</span></label>
                    <input 
                        type="text" 
                        name="companyName"
                        value={formData.companyName}
                        onChange={handleChange}
                        className={`w-full bg-black/50 border ${errors.companyName ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                    />
                    {errors.companyName && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.companyName}</span>}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                        <label className="text-sm font-medium text-gray-300">{t.auth.sector} <span className="text-brand-gold">*</span></label>
                        <select 
                            name="sector"
                            value={formData.sector}
                            onChange={handleChange}
                            className={`w-full bg-black/50 border ${errors.sector ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                        >
                            <option value="">{lang === 'en' ? 'Select Sector' : 'اختر القطاع'}</option>
                            {CATEGORIES.map(c => <option key={c.en} value={c.en}>{c[lang]}</option>)}
                        </select>
                        {errors.sector && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.sector}</span>}
                    </div>

                    <div className="space-y-2">
                        <label className="text-sm font-medium text-gray-300">{t.auth.companyAge} <span className="text-brand-gold">*</span></label>
                        <input 
                            type="number" 
                            name="companyAge"
                            value={formData.companyAge}
                            onChange={handleChange}
                            className={`w-full bg-black/50 border ${errors.companyAge ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                        />
                        {errors.companyAge && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.companyAge}</span>}
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                        <label className="text-sm font-medium text-gray-300">{t.auth.legalEntity} <span className="text-brand-gold">*</span></label>
                        <input 
                            type="text" 
                            name="legalEntity"
                            placeholder="e.g. LLC"
                            value={formData.legalEntity}
                            onChange={handleChange}
                            className={`w-full bg-black/50 border ${errors.legalEntity ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                        />
                        {errors.legalEntity && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.legalEntity}</span>}
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-medium text-gray-300">{t.auth.companyType} <span className="text-brand-gold">*</span></label>
                        <input 
                            type="text" 
                            name="companyType"
                            placeholder="e.g. Startup, SME"
                            value={formData.companyType}
                            onChange={handleChange}
                            className={`w-full bg-black/50 border ${errors.companyType ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                        />
                        {errors.companyType && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.companyType}</span>}
                    </div>
                </div>

                {/* Company Stage */}
                <div className="space-y-2">
                    <label className="text-sm font-medium text-gray-300">{t.auth.companyStage} <span className="text-brand-gold">*</span></label>
                    <select 
                        name="companyStage"
                        value={formData.companyStage}
                        onChange={handleChange}
                        className={`w-full bg-black/50 border ${errors.companyStage ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                    >
                        {COMPANY_STAGES.map(stage => (
                            <option key={stage.id} value={stage.id}>{stage.label[lang]}</option>
                        ))}
                    </select>
                    {selectedStageData && (
                        <div className="bg-brand-gold/10 border border-brand-gold/20 rounded-lg p-3 flex gap-3 text-xs mt-2">
                            <div className="flex-shrink-0 pt-0.5">
                                <Info size={16} className="text-brand-gold" />
                            </div>
                            <div className="space-y-1">
                                <p className="text-gray-300"><strong className="text-brand-gold">{lang === 'ar' ? 'الوصف: ' : 'Description: '}</strong>{selectedStageData.desc[lang]}</p>
                                <p className="text-gray-300"><strong className="text-brand-gold">{lang === 'ar' ? 'عمر النشاط: ' : 'Age: '}</strong>{selectedStageData.age[lang]}</p>
                            </div>
                        </div>
                    )}
                </div>

                {/* Financials & Reason */}
                <div className="space-y-2">
                    <label className="text-sm font-medium text-gray-300">
                        {purpose === 'sale' ? t.auth.salePrice : t.auth.requestedInvestment} <span className="text-brand-gold">*</span>
                    </label>
                    <input 
                        type="number" 
                        name="requestedInvestment"
                        value={formData.requestedInvestment}
                        onChange={handleChange}
                        className={`w-full bg-black/50 border ${errors.requestedInvestment ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                    />
                    {errors.requestedInvestment && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.requestedInvestment}</span>}
                </div>

                {purpose === 'investment' && (
                <div className="space-y-2">
                    <label className="text-sm font-medium text-gray-300">{t.auth.shareToSell} <span className="text-brand-gold">*</span></label>
                    <input 
                        type="number" 
                        name="shareToSell"
                        max="100"
                        value={formData.shareToSell}
                        onChange={handleChange}
                        className={`w-full bg-black/50 border ${errors.shareToSell ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                    />
                    {errors.shareToSell && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.shareToSell}</span>}
                </div>
                )}

                <div className="space-y-2">
                    <label className="text-sm font-medium text-gray-300">{t.auth.investmentReason} <span className="text-brand-gold">*</span></label>
                    <textarea 
                        name="investmentReason"
                        rows={3}
                        value={formData.investmentReason}
                        onChange={handleChange}
                        className={`w-full bg-black/50 border ${errors.investmentReason ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                    />
                    {errors.investmentReason && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.investmentReason}</span>}
                </div>

                <div className="space-y-2">
                    <label className="text-sm font-medium text-gray-300">{t.auth.fullDetails} <span className="text-brand-gold">*</span></label>
                    <textarea 
                        name="fullDetails"
                        rows={5}
                        value={formData.fullDetails}
                        onChange={handleChange}
                        className={`w-full bg-black/50 border ${errors.fullDetails ? 'border-red-500' : 'border-white/10'} rounded-lg px-4 py-3 text-white focus:border-brand-gold outline-none transition`}
                    />
                    {errors.fullDetails && <span className="text-xs text-red-500 flex items-center gap-1"><AlertCircle size={10} /> {errors.fullDetails}</span>}
                </div>

                <div className="flex gap-4 pt-4">
                     <button type="button" onClick={() => setStep(1)} className="flex-1 bg-white/10 text-white font-bold py-4 rounded-xl hover:bg-white/20 transition">
                        {lang === 'ar' ? 'السابق' : 'Back'}
                     </button>
                     <button 
                        type="submit" 
                        disabled={isSubmitting}
                        className="flex-[2] bg-brand-gold text-black font-bold text-lg py-4 rounded-xl hover:bg-yellow-500 transition shadow-lg shadow-brand-gold/20 disabled:opacity-50 disabled:cursor-not-allowed"
                     >
                        {isSubmitting ? (
                            <span className="flex items-center justify-center gap-2">
                            <span className="w-5 h-5 border-2 border-black/30 border-t-black rounded-full animate-spin"></span>
                            {t.listing.processing}
                            </span>
                        ) : t.listing.submit}
                    </button>
                </div>

            </form>
        )}
      </div>
    </div>
  );
};

export type Language = 'en' | 'ar';
export type UserRole = 'investor' | 'advertiser' | 'admin' | 'guest';

export interface User {
  id: string;
  name: string; // Internal name
  email: string;
  role: UserRole;
  subscriptionPlan?: 'basic' | 'premium' | 'vip';
  unlockedProjects: string[]; // IDs of projects purchased
  favorites: string[];
  companyLicenseUrl?: string; // Kept for Account Verification (KYC)
  // Legacy fields kept for backward compatibility if needed, but not used in new Signup
  companyName?: string;
  // Investor Profile
  investorType?: 'company' | 'angel' | 'crowdfunding';
  investorSector?: string;
  investorCapital?: number;
  investmentCount?: number;
  investorExperience?: 'beginner' | 'intermediate' | 'expert';
}

export interface PublicInvestor {
  id: string;
  investorType: 'company' | 'angel' | 'crowdfunding';
  capital: number;
  preferredField: string; // Category EN
  experience: 'beginner' | 'intermediate' | 'expert';
}

export type ListingPurpose = 'investment' | 'sale';

export interface Project {
  id: string;
  ownerId?: string; // Link to the Advertiser User
  listingPurpose?: ListingPurpose; // New field
  name: { ar: string; en: string };
  category: { ar: string; en: string };
  image: string; // URL to thumbnail
  capital: number; // KWD
  age: { ar: string; en: string };
  shareOffered: number; // %
  askingPrice: number; // KWD (Requested Investment Amount or Sale Price)
  location: { ar: string; en: string };
  descriptionShort: { ar: string; en: string };
  descriptionFull: { ar: string; en: string };
  financialHealth: 'Strong' | 'Stable' | 'Growing' | 'Recovering' | 'New';
  status: 'pending' | 'active' | 'funded';
  createdAt: string;
  // Details
  legalEntity?: { ar: string; en: string };
  companyType?: { ar: string; en: string };
  companyStage?: { ar: string; en: string }; 
  investmentReason?: { ar: string; en: string };
}

export interface SubscriptionPlan {
  id: string;
  name: { en: string; ar: string };
  price: number;
  features: { en: string[]; ar: string[] };
  isPopular?: boolean;
}

export type SortOption = 'price_asc' | 'price_desc' | 'newest' | 'share_high';

export interface FilterState {
  category: string;
  minPrice: number;
  maxPrice: number;
  sort: SortOption;
}

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/Store';
import { TRANSLATIONS, CATEGORIES, SAMPLE_INVESTORS } from '../constants';
import { Filter, Users, DollarSign, Briefcase, Award } from 'lucide-react';
import { PublicInvestor } from '../types';

export const Investors: React.FC = () => {
  const { lang } = useStore();
  const t = TRANSLATIONS[lang];
  const p = t.investorsPage;

  // Filter States
  const [filterType, setFilterType] = useState<string>('');
  const [filterExp, setFilterExp] = useState<string>('');
  const [filterField, setFilterField] = useState<string>('');
  const [filterCapital, setFilterCapital] = useState<string>('');

  // Filtering Logic
  const filteredInvestors = useMemo(() => {
    let result = [...SAMPLE_INVESTORS];

    if (filterType) {
      result = result.filter(i => i.investorType === filterType);
    }
    if (filterExp) {
      result = result.filter(i => i.experience === filterExp);
    }
    if (filterField) {
      result = result.filter(i => i.preferredField === filterField);
    }
    if (filterCapital) {
      // Basic Range Filtering Demo
      if (filterCapital === 'low') result = result.filter(i => i.capital < 100000);
      else if (filterCapital === 'mid') result = result.filter(i => i.capital >= 100000 && i.capital < 500000);
      else if (filterCapital === 'high') result = result.filter(i => i.capital >= 500000);
    }

    return result;
  }, [filterType, filterExp, filterField, filterCapital]);

  const formatCurrency = (val: number) => new Intl.NumberFormat(lang === 'en' ? 'en-KW' : 'ar-KW', { style: 'currency', currency: 'KWD', maximumFractionDigits: 0 }).format(val);

  // Helper for translated values
  const getTypeLabel = (type: string) => {
     if (type === 'angel') return t.listing.angelType;
     if (type === 'company') return t.listing.companyType;
     if (type === 'crowdfunding') return t.listing.crowdType;
     return type;
  };

  const getExpLabel = (exp: string) => {
     if (exp === 'beginner') return t.auth.expBeginner;
     if (exp === 'intermediate') return t.auth.expIntermediate;
     if (exp === 'expert') return t.auth.expExpert;
     return exp;
  };

  const getFieldLabel = (fieldEn: string) => {
     const cat = CATEGORIES.find(c => c.en === fieldEn);
     return cat ? cat[lang] : fieldEn;
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">

      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold mb-2 text-white">{p.title}</h1>
        <p className="text-gray-400">{p.subtitle}</p>
      </div>

      <div className="flex flex-col md:flex-row gap-8">

        {/* Sidebar Filters */}
        <aside className="w-full md:w-1/4 space-y-8">
          <div className="bg-brand-gray p-6 rounded-xl border border-white/5 sticky top-24">
            <div className="flex items-center gap-2 mb-6 text-brand-gold">
              <Filter size={20} />
              <h3 className="font-bold text-lg">{p.filterTitle}</h3>
            </div>

            <div className="space-y-6">
              {/* Type Filter */}
              <div>
                <label className="block text-sm font-medium mb-2 text-gray-400">{p.filterType}</label>
                <select 
                  className="w-full bg-black border border-white/20 rounded-lg p-2 text-sm focus:border-brand-gold outline-none"
                  value={filterType}
                  onChange={(e) => setFilterType(e.target.value)}
                >
                  <option value="">{p.allTypes}</option>
                  <option value="company">{t.listing.companyType}</option>
                  <option value="angel">{t.listing.angelType}</option>
                  <option value="crowdfunding">{t.listing.crowdType}</option>
                </select>
              </div>

              {/* Capital Filter */}
              <div>
                <label className="block text-sm font-medium mb-2 text-gray-400">{p.filterCapital}</label>
                <select 
                  className="w-full bg-black border border-white/20 rounded-lg p-2 text-sm focus:border-brand-gold outline-none"
                  value={filterCapital}
                  onChange={(e) => setFilterCapital(e.target.value)}
                >
                  <option value="">{lang === 'en' ? 'Any Amount' : 'أي مبلغ'}</option>
                  <option value="low">{lang === 'en' ? 'Under 100K' : 'أقل من ١٠٠ ألف'}</option>
                  <option value="mid">{lang === 'en' ? '100K - 500K' : '١٠٠ ألف - ٥٠٠ ألف'}</option>
                  <option value="high">{lang === 'en' ? '500K+' : '٥٠٠ ألف +'}</option>
                </select>
              </div>

              {/* Experience Filter */}
              <div>
                <label className="block text-sm font-medium mb-2 text-gray-400">{p.filterExp}</label>
                <select 
                  className="w-full bg-black border border-white/20 rounded-lg p-2 text-sm focus:border-brand-gold outline-none"
                  value={filterExp}
                  onChange={(e) => setFilterExp(e.target.value)}
                >
                  <option value="">{p.allExp}</option>
                  <option value="beginner">{t.auth.expBeginner}</option>
                  <option value="intermediate">{t.auth.expIntermediate}</option>
                  <option value="expert">{t.auth.expExpert}</option>
                </select>
              </div>

              {/* Field Filter */}
              <div>
                <label className="block text-sm font-medium mb-2 text-gray-400">{p.filterField}</label>
                <select 
                  className="w-full bg-black border border-white/20 rounded-lg p-2 text-sm focus:border-brand-gold outline-none"
                  value={filterField}
                  onChange={(e) => setFilterField(e.target.value)}
                >
                  <option value="">{p.allFields}</option>
                  {CATEGORIES.map(c => <option key={c.en} value={c.en}>{c[lang]}</option>)}
                </select>
              </div>

              <button 
                onClick={() => { setFilterType(''); setFilterExp(''); setFilterField(''); setFilterCapital(''); }}
                className="w-full text-sm text-gray-500 hover:text-white underline mt-4"
              >
                {p.reset}
              </button>
            </div>
          </div>
        </aside>

        {/* Results Grid */}
        <div className="w-full md:w-3/4">
           <div className="flex items-center justify-between mb-6">
             <h2 className="text-2xl font-bold flex items-center gap-3">
               <Users className="text-brand-gold" />
               {p.title} <span className="text-gray-500 text-lg font-normal">({filteredInvestors.length})</span>
             </h2>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
             {filteredInvestors.map(investor => (
