export const ProjectDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { lang, projects, user, unlockProject, isProjectUnlocked, requestInterest } = useStore();
  const t = TRANSLATIONS[lang];

  const [showStageTooltip, setShowStageTooltip] = useState(false);
  const stageCardRef = useRef<HTMLDivElement>(null);

  const project = projects.find(p => p.id === id);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (stageCardRef.current && !stageCardRef.current.contains(event.target as Node)) {
        setShowStageTooltip(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  if (!project) return <Navigate to="/projects" />;

  const unlocked = isProjectUnlocked(project.id);
  const formatCurrency = (val: number) => new Intl.NumberFormat(lang === 'en' ? 'en-KW' : 'ar-KW', { style: 'currency', currency: 'KWD' }).format(val);

  // Get localized financial health
  const healthKey = project.financialHealth;
  const localizedHealth = FINANCIAL_HEALTH_MAP[healthKey] ? FINANCIAL_HEALTH_MAP[healthKey][lang] : healthKey;

  // Get Stage Info for Tooltip
  const stageInfo = COMPANY_STAGES.find(s => s.label.en === project.companyStage?.en);

  const handlePurchase = () => {
    if (!user) {
      navigate('/login-type');
      return;
    }
    unlockProject(project.id);
  };

  return (
    <div className="max-w-5xl mx-auto px-4 py-12">
      {/* Header Card - Refactored for Stacking Context (Z-Index Fix) */}
      <div className="relative mb-8 z-20 group">

        {/* 1. Background Layer (Image + Gradient) - Handles clipping and borders */}
        <div className="absolute inset-0 rounded-2xl overflow-hidden border border-white/10 bg-brand-gray pointer-events-none">
          <div className="absolute inset-0">
            <img src={project.image} alt={project.name[lang]} className="w-full h-full object-cover opacity-40 group-hover:scale-105 transition duration-[2s]" />
            <div className="absolute inset-0 bg-gradient-to-r from-brand-gray via-brand-gray/90 to-transparent"></div>
          </div>
        </div>

        {/* 2. Content Layer - No overflow hidden, allows tooltip to pop out */}
        <div className="relative p-8">
          <div className="flex flex-col md:flex-row justify-between items-start mb-8">
            <div>
              <span className={`bg-brand-gold text-black px-3 py-1 rounded text-xs font-bold uppercase tracking-widest ${lang === 'ar' ? 'inline-block mb-4' : ''}`}>
                {project.category[lang]}
              </span>
              <h1 className={`text-3xl md:text-5xl font-bold mb-2 text-white shadow-black drop-shadow-lg ${lang === 'ar' ? 'leading-normal' : 'mt-4'}`}>
                {project.name[lang]}
              </h1>
              <p className="text-gray-300 text-sm flex items-center gap-2 mt-2">
                 <span className="opacity-60">ID: {project.id}</span>
                 <span className="w-1 h-1 rounded-full bg-gray-500"></span>
                 <span className="flex items-center gap-1 text-brand-gold"><MapPin size={12}/> {project.location[lang]}</span>
              </p>
            </div>
            <div className="mt-4 md:mt-0 bg-black/60 backdrop-blur-md px-4 py-2 rounded-lg border border-white/10">
               <span className={`font-bold ${unlocked ? 'text-green-400' : 'text-gray-400'} flex items-center gap-2`}>
                  {unlocked ? <Unlock size={16} /> : <Lock size={16} />}
                  {unlocked ? t.common.unlocked : t.common.locked}
               </span>
            </div>
          </div>

          {/* Group A: Public Stats Grid */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">

            {/* Card 1: Investment Amount */}
            <div className="bg-black/60 backdrop-blur-md p-4 rounded-xl border border-white/10 hover:border-brand-gold/30 transition flex flex-col justify-center min-h-[100px] min-w-0">
              <div className="flex items-start gap-2 text-gray-400 mb-1.5 text-xs uppercase w-full">
                <DollarSign size={14} className="shrink-0 mt-0.5"/> 
                <span className="line-clamp-2 leading-tight">{t.auth.requestedInvestment}</span>
              </div>
              <div className="text-xs sm:text-sm md:text-lg font-bold text-white whitespace-nowrap overflow-hidden text-ellipsis leading-tight">
