import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, UserRole, Project, Language } from '../types';
import { SAMPLE_PROJECTS } from '../constants';

interface StoreContextType {
  user: User | null;
  lang: Language;
  projects: Project[];
  toggleLanguage: () => void;
  login: (role: UserRole | 'company', email?: string) => void;
  logout: () => void;
  unlockProject: (projectId: string) => void;
  isProjectUnlocked: (projectId: string) => boolean;
  requestInterest: (projectId: string) => void;
  toggleFavorite: (projectId: string) => void;
  isFavorite: (projectId: string) => boolean;
  addProject: (projectData: Partial<Project>) => void; // New function
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [lang, setLang] = useState<Language>('ar');
  const [user, setUser] = useState<User | null>(null);
  const [projects, setProjects] = useState<Project[]>(SAMPLE_PROJECTS);

  // Layout direction effect
  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
  }, [lang]);

  const toggleLanguage = () => setLang(prev => prev === 'en' ? 'ar' : 'en');

  const login = (roleInput: UserRole | 'company', email: string = 'user@bi-platform.com') => {
    // Migration/Normalization: Handle legacy 'company' role input
    const role: UserRole = roleInput === 'company' ? 'advertiser' : roleInput;

    // Mock login with random ID and provided email
    // If role is advertiser (formerly company), we simulate a license URL being present
    const licenseUrl = role === 'advertiser' 
      ? 'https://images.unsplash.com/photo-1563986768609-322da13575f3?auto=format&fit=crop&w=400&q=80' // Mock Document Image
      : undefined;

    setUser({
      id: `USR-${Math.floor(Math.random() * 10000)}`,
      name: role === 'advertiser' ? 'Business Owner' : 'Verified Investor',
      email: email,
      role: role,
      subscriptionPlan: role === 'investor' ? 'premium' : undefined,
      unlockedProjects: [],
      favorites: [],
      companyLicenseUrl: licenseUrl
    });
  };

  const logout = () => setUser(null);

  const unlockProject = (projectId: string) => {
    if (!user) return;
    if (user.unlockedProjects.includes(projectId)) return;

    // Simulate payment success
    setUser({ ...user, unlockedProjects: [...user.unlockedProjects, projectId] });
    alert(lang === 'en' ? 'Payment Successful. File Unlocked.' : 'تم الدفع بنجاح. تم فتح الملف.');
  };

  const isProjectUnlocked = (projectId: string) => {
    if (!user) return false;
    return user.unlockedProjects.includes(projectId);
  };

  const requestInterest = (projectId: string) => {
    alert(lang === 'en' ? 'Interest registered. Admin will contact you shortly.' : 'تم تسجيل اهتمامك. سيتصل بك المسؤول قريباً.');
  };

  const toggleFavorite = (projectId: string) => {
    if (!user) {
      alert(lang === 'en' ? 'Please login to save favorites.' : 'يرجى تسجيل الدخول لحفظ المفضلة.');
      return;
    }

    const isFav = user.favorites.includes(projectId);
    const newFavorites = isFav 
      ? user.favorites.filter(id => id !== projectId)
      : [...user.favorites, projectId];

    setUser({ ...user, favorites: newFavorites });
  };

  const isFavorite = (projectId: string) => {
    if (!user) return false;
    return user.favorites.includes(projectId);
  };

  // Add Project / Listing
  const addProject = (projectData: Partial<Project>) => {
    if (!user) return;

    const newProject: Project = {
       id: `PROJ-${Math.floor(Math.random() * 100000)}`,
       ownerId: user.id,
       name: projectData.name || { ar: 'مشروع جديد', en: 'New Project' },
       category: projectData.category || { ar: 'غير محدد', en: 'Uncategorized' },
       image: projectData.image || "https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80",
       capital: projectData.capital || 0,
       age: projectData.age || { ar: '0 سنوات', en: '0 Years' },
       shareOffered: projectData.shareOffered || 0,
       askingPrice: projectData.askingPrice || 0,
       location: projectData.location || { ar: 'الكويت', en: 'Kuwait' },
       descriptionShort: projectData.descriptionShort || { ar: '', en: '' },
       descriptionFull: projectData.descriptionFull || { ar: '', en: '' },
       financialHealth: projectData.financialHealth || 'Stable',
       status: 'pending',
       createdAt: new Date().toISOString(),
       listingPurpose: projectData.listingPurpose || 'investment',
       ...projectData
    } as Project;

    setProjects(prev => [newProject, ...prev]);
  };

  return (
    <StoreContext.Provider value={{ 
      user, lang, projects, toggleLanguage, login, logout, unlockProject, isProjectUnlocked, requestInterest, toggleFavorite, isFavorite, addProject
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error("useStore must be used within StoreProvider");
  return context;
};

export type Language = 'en' | 'ar';
export type UserRole = 'investor' | 'advertiser' | 'admin' | 'guest';

export interface User {
  id: string;
  name: string; // Internal name
  email: string;
  role: UserRole;
  subscriptionPlan?: 'basic' | 'premium' | 'vip';
  unlockedProjects: string[]; // IDs of projects purchased
  favorites: string[];
  companyLicenseUrl?: string; // Kept for Account Verification (KYC)
  // Legacy fields kept for backward compatibility if needed, but not used in new Signup
  companyName?: string;
  // Investor Profile
  investorType?: 'company' | 'angel' | 'crowdfunding';
  investorSector?: string;
  investorCapital?: number;
  investmentCount?: number;
  investorExperience?: 'beginner' | 'intermediate' | 'expert';
}

export interface PublicInvestor {
  id: string;
  investorType: 'company' | 'angel' | 'crowdfunding';
  capital: number;
  preferredField: string; // Category EN
  experience: 'beginner' | 'intermediate' | 'expert';
}

export type ListingPurpose = 'investment' | 'sale';

export type FinancialStatus = 
  | 'Very Strong' 
  | 'Strong' 
  | 'Stable' 
  | 'Moderate' 
  | 'Needs Improvement' 
  | 'Weak' 
  | 'Critical' 
  | 'Not Disclosed' 
  | 'Unknown';

export interface Project {
  id: string;
  ownerId?: string; // Link to the Advertiser User
  listingPurpose?: ListingPurpose; // New field
  name: { ar: string; en: string };
  category: { ar: string; en: string };
  image: string; // URL to thumbnail
  capital: number; // KWD
  age: { ar: string; en: string };
  shareOffered: number; // %
  askingPrice: number; // KWD (Requested Investment Amount or Sale Price)
  location: { ar: string; en: string };
  descriptionShort: { ar: string; en: string };
  descriptionFull: { ar: string; en: string };
  financialHealth: FinancialStatus;
  status: 'pending' | 'active' | 'funded';
  createdAt: string;
  // Details
  legalEntity?: { ar: string; en: string };
  companyType?: { ar: string; en: string };
  companyStage?: { ar: string; en: string }; 
  investmentReason?: { ar: string; en: string };
}

export interface SubscriptionPlan {
  id: string;
  name: { en: string; ar: string };
  price: number;
  features: { en: string[]; ar: string[] };
  isPopular?: boolean;
}

export type SortOption = 'price_asc' | 'price_desc' | 'newest' | 'share_high';

export interface FilterState {
  category: string;
  minPrice: number;
  maxPrice: number;
  sort: SortOption;
}

import React, { useState } from 'react';
import { useStore } from '../context/Store';
import { Navigate, useNavigate } from 'react-router-dom';
import { TRANSLATIONS, CATEGORIES, COMPANY_STAGES, FINANCIAL_STATUS_ORDER, FINANCIAL_HEALTH_MAP } from '../constants';
import { ArrowLeft, ArrowRight, TrendingUp, Store, Info, CheckCircle, AlertCircle } from 'lucide-react';
import { ListingPurpose, FinancialStatus } from '../types';

export const AddListing: React.FC = () => {
  const { user, lang, addProject } = useStore();
  const navigate = useNavigate();
  const t = TRANSLATIONS[lang];

  const [step, setStep] = useState(1);
  const [purpose, setPurpose] = useState<ListingPurpose>('investment');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Form State
  const [formData, setFormData] = useState({
    companyName: '',
    sector: '',
    companyAge: '',
    legalEntity: '',
    companyType: '',
    companyStage: 'seed',
    financialHealth: 'Stable' as FinancialStatus,
    requestedInvestment: '', // Reused for Sales Price based on context
    investmentReason: '',
    shareToSell: '',
    fullDetails: ''
  });

  if (!user || user.role !== 'advertiser') return <Navigate to="/dashboard" />;

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: '' }));
  };

  const validateStep2 = () => {
    const newErrors: Record<string, string> = {};
    if (!formData.companyName.trim()) newErrors.companyName = t.auth.required;
    if (!formData.sector.trim()) newErrors.sector = t.auth.required;
    if (!formData.companyAge.trim()) newErrors.companyAge = t.auth.required;
    if (!formData.legalEntity.trim()) newErrors.legalEntity = t.auth.required;
    if (!formData.companyType.trim()) newErrors.companyType = t.auth.required;
    if (!formData.financialHealth.trim()) newErrors.financialHealth = t.auth.required;
    if (!formData.requestedInvestment.trim()) newErrors.requestedInvestment = t.auth.required;
    // Share percentage is only required for investment listings
    if (purpose === 'investment' && !formData.shareToSell.trim()) {
        newErrors.shareToSell = t.auth.required;
    }
    if (!formData.fullDetails.trim()) newErrors.fullDetails = t.auth.required;
    if (!formData.investmentReason.trim()) newErrors.investmentReason = t.auth.required;

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validateStep2()) {
      setIsSubmitting(true);

      // Construct Project Object
      // In a real app, this would be an API call
      setTimeout(() => {
        addProject({
            listingPurpose: purpose,
            name: { ar: formData.companyName, en: formData.companyName },
            category: { ar: CATEGORIES.find(c => c.en === formData.sector)?.ar || 'عام', en: formData.sector },
            askingPrice: parseFloat(formData.requestedInvestment),
            age: { ar: `${formData.companyAge} سنوات`, en: `${formData.companyAge} Years` },
            shareOffered: purpose === 'sale' ? 100 : parseFloat(formData.shareToSell),
            legalEntity: { ar: formData.legalEntity, en: formData.legalEntity },
            companyType: { ar: formData.companyType, en: formData.companyType },
            companyStage: { 
                ar: COMPANY_STAGES.find(s => s.id === formData.companyStage)?.label.ar || '', 
                en: COMPANY_STAGES.find(s => s.id === formData.companyStage)?.label.en || '' 
            },
            financialHealth: formData.financialHealth,
            investmentReason: { ar: formData.investmentReason, en: formData.investmentReason },
            descriptionShort: { ar: formData.investmentReason.substring(0, 100) + '...', en: formData.investmentReason.substring(0, 100) + '...' },
            descriptionFull: { ar: formData.fullDetails, en: formData.fullDetails }
        });

        setIsSubmitting(false);
        alert(t.listing.success);
        navigate('/dashboard');
      }, 1500);
    }
  };

  const selectedStageData = COMPANY_STAGES.find(s => s.id === formData.companyStage);

  return (
    <div className="max-w-3xl mx-auto px-4 py-12">

      {/* Progress */}
      <div className="flex items-center justify-between mb-8">
         <h1 className="text-2xl font-bold">{t.listing.title}</h1>
         <div className="flex items-center gap-2 text-sm text-gray-400">
            <span className={step === 1 ? 'text-brand-gold font-bold' : ''}>1. {t.listing.step1}</span>
            <span>&rarr;</span>
            <span className={step === 2 ? 'text-brand-gold font-bold' : ''}>2. {t.listing.step2}</span>
         </div>
      </div>

      <div className="bg-brand-gray/20 border border-white/10 rounded-2xl p-8 backdrop-blur-sm animate-fade-in">

        {step === 1 && (
            <div className="space-y-6">
                <h2 className="text-xl font-bold text-center mb-6">{t.listing.purposeTitle}</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <button 
                        onClick={() => setPurpose('investment')}
                        className={`p-6 rounded-xl border text-left transition-all group ${purpose === 'investment' ? 'bg-brand-gold text-black border-brand-gold' : 'bg-black/40 border-white/10 hover:border-brand-gold/50'}`}
                    >
                        <TrendingUp size={32} className={`mb-4 ${purpose === 'investment' ? 'text-black' : 'text-brand-gold'}`} />
                        <h3 className="font-bold text-lg mb-1">{t.listing.investment}</h3>
                        <p className={`text-sm ${purpose === 'investment' ? 'text-black/70' : 'text-gray-400'}`}>{t.listing.investmentDesc}</p>
                    </button>

                    <button 
                        onClick={() => setPurpose('sale')}
                        className={`p-6 rounded-xl border text-left transition-all group ${purpose === 'sale' ? 'bg-brand-gold text-black border-brand-gold' : 'bg-black/40 border-white/10 hover:border-brand-gold/50'}`}
                    >
                        <Store size={32} className={`mb-4 ${purpose === 'sale' ? 'text-black' : 'text-brand-gold'}`} />
                        <h3 className="font-bold text-lg mb-1">{t.listing.sale}</h3>
