               {showStageTooltip && stageInfo && (
                 <div className="absolute top-[calc(100%+12px)] left-1/2 -translate-x-1/2 w-64 bg-brand-dark border border-brand-gold/30 p-4 rounded-xl shadow-2xl z-[100] animate-fade-in cursor-default" onClick={(e) => e.stopPropagation()}>
