                       <strong className="block text-brand-gold mb-2 border-b border-brand-gold/20 pb-2">{stageInfo.label[lang]}</strong>
                       {stageInfo.desc[lang]}
                    </div>
                    {/* Arrow */}
                    <div className="absolute bottom-full left-1/2 -translate-x-1/2 w-0 h-0 border-l-[8px] border-l-transparent border-r-[8px] border-r-transparent border-b-[8px] border-b-brand-dark"></div>
                 </div>
