                          <span className="text-xs text-brand-gold uppercase tracking-wider font-bold bg-brand-gold/10 px-2 py-0.5 rounded border border-brand-gold/20">
                            {getTypeLabel(investor.investorType)}
                          </span>
                       </div>
                    </div>
                 </div>

                 <div className="space-y-4">
                    <div className="flex items-center justify-between p-3 bg-black/20 rounded-lg border border-white/5">
                       <div className="flex items-center gap-2 text-gray-400 text-sm">
                          <DollarSign size={16} className="text-brand-gold" />
                          <span>{t.auth.investorCapital}</span>
                       </div>
                       <span className="font-bold text-white">{formatCurrency(investor.capital)}</span>
                    </div>

                    <div className="flex items-center justify-between p-3 bg-black/20 rounded-lg border border-white/5">
                       <div className="flex items-center gap-2 text-gray-400 text-sm">
                          <Briefcase size={16} className="text-brand-gold" />
                          <span>{t.auth.investorSector}</span>
                       </div>
                       <span className="font-bold text-white">{getFieldLabel(investor.preferredField)}</span>
                    </div>

                    <div className="flex items-center justify-between p-3 bg-black/20 rounded-lg border border-white/5">
                       <div className="flex items-center gap-2 text-gray-400 text-sm">
                          <Award size={16} className="text-brand-gold" />
                          <span>{t.auth.investorExperience}</span>
                       </div>
                       <span className="font-bold text-white">{getExpLabel(investor.experience)}</span>
                    </div>
                 </div>

               </div>
             ))}
           </div>

           {filteredInvestors.length === 0 && (
             <div className="text-center py-20 bg-brand-gray/20 rounded-xl border border-dashed border-white/10">
               <Users className="mx-auto text-gray-600 mb-4" size={48} />
               <p className="text-gray-400 text-lg">{lang === 'en' ? 'No investors found matching your filters.' : 'لا يوجد مستثمرين يطابقون اختيارك.'}</p>
               <button 
                  onClick={() => { setFilterType(''); setFilterExp(''); setFilterField(''); setFilterCapital(''); }}
                  className="mt-4 text-brand-gold hover:underline"
               >
                 {p.reset}
               </button>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

export type Language = 'en' | 'ar';
export type UserRole = 'investor' | 'advertiser' | 'admin' | 'guest';

export interface User {
  id: string;
  name: string; // Internal name
  email: string;
  role: UserRole;
  subscriptionPlan?: 'basic' | 'premium' | 'vip';
  unlockedProjects: string[]; // IDs of projects purchased
  favorites: string[];
  companyLicenseUrl?: string; // Kept for Account Verification (KYC)
  // Legacy fields kept for backward compatibility if needed, but not used in new Signup
  companyName?: string;
  // Investor Profile
  investorType?: 'company' | 'angel' | 'crowdfunding';
  investorSector?: string;
  investorCapital?: number;
  investmentCount?: number;
  investorExperience?: 'beginner' | 'intermediate' | 'expert';
}

export interface PublicInvestor {
  id: string;
  investorType: 'company' | 'angel' | 'crowdfunding';
  capital: number;
  preferredField: string; // Category EN
  experience: 'beginner' | 'intermediate' | 'expert';
}

export type ListingPurpose = 'investment' | 'sale';

export type FinancialStatus = 
  | 'Very Strong' 
  | 'Strong' 
  | 'Stable' 
  | 'Moderate' 
  | 'Needs Improvement' 
  | 'Weak' 
  | 'Critical' 
  | 'Not Disclosed' 
  | 'Unknown';

export interface Project {
  id: string;
  ownerId?: string; // Link to the Advertiser User
  listingPurpose?: ListingPurpose; // New field
  name: { ar: string; en: string };
  category: { ar: string; en: string };
  image: string; // URL to thumbnail
  capital: number; // KWD
  age: { ar: string; en: string };
  shareOffered: number; // %
  askingPrice: number; // KWD (Requested Investment Amount or Sale Price)
  location: { ar: string; en: string };
  descriptionShort: { ar: string; en: string };
  descriptionFull: { ar: string; en: string };
  financialHealth: FinancialStatus;
  status: 'pending' | 'active' | 'funded';
  createdAt: string;
  // Details
  legalEntity?: { ar: string; en: string };
  companyType?: { ar: string; en: string };
  companyStage?: { ar: string; en: string }; 
  investmentReason?: { ar: string; en: string };
  // Stats
  viewsCount?: number;
  bookletPurchasesCount?: number;
  interestsCount?: number;
}

export interface SubscriptionPlan {
  id: string;
  name: { en: string; ar: string };
  price: number;
  features: { en: string[]; ar: string[] };
  isPopular?: boolean;
}

export type SortOption = 'price_asc' | 'price_desc' | 'newest' | 'share_high';

export interface FilterState {
  category: string;
  minPrice: number;
  maxPrice: number;
  sort: SortOption;
}

