import React, { useMemo } from 'react';
import { useStore } from '../context/Store';
import { TRANSLATIONS, SAMPLE_INVESTORS, EXTRA_STATS } from '../constants';
import { Logo } from './Logo';
import { Globe, User as UserIcon, LogOut, Home, Briefcase, LayoutDashboard, MoreHorizontal, Users } from 'lucide-react';
import { Link, useLocation } from 'react-router-dom';

export const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { lang, toggleLanguage, user, logout, projects } = useStore();

  // Safety check for translations
  const t = TRANSLATIONS[lang] || TRANSLATIONS['en'];

  const location = useLocation();

  const isActive = (path: string) => location.pathname === path ? "text-brand-gold font-bold" : "text-gray-300 hover:text-white transition-colors";

  // Calculate Total Stats for Badge
  const totalStats = useMemo(() => {
    return projects.length + 
           SAMPLE_INVESTORS.length + 
           EXTRA_STATS.companyOwners + 
           EXTRA_STATS.proposedDeals + 
           EXTRA_STATS.successfulDeals;
  }, [projects]);

  // Mobile Tab Bar Item Component
  const TabItem = ({ to, icon: Icon, label }: { to: string, icon: any, label: string }) => {
    const active = location.pathname === to;
    const colorClass = active ? "text-brand-gold" : "text-gray-500";

    return (
      <Link to={to} className="flex-1 h-full flex items-center justify-center">
        <div className={`flex flex-col items-center justify-center w-full h-full gap-1 ${colorClass}`}>
          <Icon size={24} strokeWidth={active ? 2.5 : 2} />
          <span className="text-[10px] font-medium">{label}</span>
        </div>
      </Link>
    );
  };

  if (!t) return null; // Should not happen with fallback

  return (
    <div className="min-h-screen bg-brand-black flex flex-col text-white transition-all duration-300">
      {/* Top Navbar (Desktop + Mobile) */}
      <nav className="fixed w-full z-40 bg-black/80 backdrop-blur-md border-b border-white/10 top-0">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-20">
            <div className="flex items-center gap-3">
              <Link to="/" className="relative inline-flex items-center justify-center overflow-visible rounded-full">
                 {/* Logo Glow Effect - Enhanced Intensity */}
                 <div className="absolute -inset-[26px] rounded-full blur-[22px] z-0 pointer-events-none bg-[radial-gradient(circle,rgba(212,175,55,0.75)_0%,rgba(212,175,55,0.35)_40%,rgba(212,175,55,0.00)_70%)]"></div>
                 <Logo className="w-10 h-10 relative z-10" />
              </Link>
              <span className="text-lg font-bold tracking-wide hidden md:block uppercase">
                 {lang === 'en' ? 'Business & Investments' : 'الأعمال والاستثمارات'}
              </span>
            </div>

            {/* Desktop Menu */}
            <div className="hidden md:flex items-center gap-8">
              <Link to="/" className={isActive('/')}>{t.nav.home}</Link>
              <Link to="/projects" className={isActive('/projects')}>{t.nav.projects}</Link>
              <Link to="/investors" className={isActive('/investors')}>{t.nav.investors}</Link>
              <Link to="/pricing" className={isActive('/pricing')}>{t.nav.pricing}</Link>
              <Link to="/about" className={isActive('/about')}>{t.nav.about}</Link>

              {/* Stats Button */}
              <Link 
                to="/stats" 
                className="flex items-center gap-2 bg-emerald-600/10 border border-emerald-500/40 text-emerald-400 px-4 py-1.5 rounded-full hover:bg-emerald-600 hover:text-white transition group"
              >
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse group-hover:bg-white"></div>
                <span className="text-sm font-bold">{t.nav.stats}</span>
                <span className="bg-emerald-500 text-black text-[10px] font-bold px-1.5 rounded-full group-hover:bg-white group-hover:text-emerald-600 transition">
                  {totalStats}
