              </Link>

              <button onClick={toggleLanguage} className="flex items-center gap-1 text-sm border border-white/20 px-3 py-1 rounded-full hover:bg-white/10 transition">
                <Globe size={14} />
                {lang === 'en' ? 'العربية' : 'English'}
