                  value={filterPurpose}
                  onChange={(e) => setFilterPurpose(e.target.value as ListingPurpose | '')}
                >
                  <option value="">{t.filters.allTypes}</option>
                  <option value="sale">{t.filters.forSale}</option>
                  <option value="investment">{t.filters.forInvestment}</option>
                </select>
              </div>

