                       </div>
                     </div>

                     {/* Content */}
                     <div className="flex-1 p-6 flex flex-col justify-between">
                       <div className="relative">
                          {/* Desktop Status Badge Only */}
                          <div className={`absolute top-0 hidden md:block ${lang === 'ar' ? 'left-0' : 'right-0'}`}>
                             {unlocked ? (
                               <span className="flex items-center gap-1 text-green-400 text-xs font-bold uppercase tracking-wider bg-green-900/20 px-2 py-1 rounded border border-green-500/20">
                                 <Unlock size={12} /> {t.common.unlocked}
                               </span>
                             ) : (
                               <span className="flex items-center gap-1 text-gray-400 text-xs font-bold uppercase tracking-wider bg-black/30 px-2 py-1 rounded border border-white/10">
                                 <Lock size={12} /> {t.common.locked}
                               </span>
                             )}
                          </div>

                          <div className="flex items-center gap-2 mb-1">
                             <span className="text-brand-gold text-xs font-bold uppercase tracking-widest block">{project.category[lang]}</span>
                             <span className="w-1 h-1 rounded-full bg-gray-600"></span>
                             <span className="text-gray-400 text-xs font-bold uppercase tracking-widest block">
                                {project.listingPurpose === 'sale' ? t.filters.forSale : t.filters.forInvestment}
