/**
 * Formats a number as currency with strict formatting rules:
 * 1. Always uses Western digits (0-9).
 * 2. Currency symbol is always on the RIGHT (after the amount).
 * 3. Uses 'en-US' locale for separators (e.g., 10,000).
 * 
 * Output Examples:
 * - English: "25,000 KWD"
 * - Arabic: "25,000 د.ك"
 */
export const formatMoney = (amount: number, lang: string): string => {
  const formattedAmount = new Intl.NumberFormat('en-US', {
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount);

  const currency = lang === 'ar' ? 'د.ك' : 'KWD';

  // Note: The consuming component must wrap this in <span className="money-ltr"> 
  // to ensure the visual order (Number then Currency) is preserved in RTL layouts.
  return `${formattedAmount} ${currency}`;
};

import React from 'react';
import { useStore } from '../context/Store';

interface MoneyProps {
  value: number;
  className?: string;
}

export const Money: React.FC<MoneyProps> = ({ value, className = '' }) => {
  const { lang } = useStore();

  // 1. Always format digits using Western numbers
  const formattedValue = new Intl.NumberFormat('en-US', {
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(value);

  const currency = lang === 'ar' ? 'د.ك' : 'KWD';

  // 2. Render money with a wrapper that controls direction per language
  // Arabic (rtl): DOM is [Number] [Currency]. RTL layout puts Number on Right, Currency on Left. Visual: Currency Number.
  // English (ltr): DOM is [Number] [Currency]. LTR layout puts Number on Left, Currency on Right. Visual: Number Currency.
  return (
    <span
      className={`money ${className}`}
      dir={lang === 'ar' ? 'rtl' : 'ltr'}
    >
      <bdi dir="ltr">{formattedValue}</bdi>
      <span className="currency">&nbsp;{currency}</span>
    </span>
  );
};

// Money formatting is now handled by the <Money /> component in components/Money.tsx
// This file is kept if other utilities are needed in the future.
export const formatMoney = (amount: number, lang: string): string => {
   // Deprecated: prefer using <Money value={amount} /> component
   return amount.toString();
};

