            <div className="space-y-6">

              <div>
                <h3 className="text-gray-400 text-sm font-bold uppercase mb-2">{t.auth.investmentReason}</h3>
                <p className="text-gray-300 leading-relaxed">
                  {project.investmentReason ? project.investmentReason[lang] : project.descriptionShort[lang]}
                </p>
              </div>
              <div>
                 <h3 className="text-gray-400 text-sm font-bold uppercase mb-2">{lang === 'en' ? 'Activity Description' : 'وصف النشاط'}</h3>
                 <p className="text-gray-300 leading-relaxed">
                   {project.descriptionShort[lang]}
                 </p>
              </div>
            </div>
          </div>

          {/* Group B: Project File / Locked Details */}
          {unlocked ? (
            <div className="bg-green-900/10 border border-green-500/20 p-8 rounded-xl animate-fade-in">
              <h2 className="text-xl font-bold mb-4 border-b border-green-500/20 pb-4 text-green-400 flex items-center gap-2">
                <Unlock size={20} /> {lang === 'en' ? 'Project File (Full Details)' : 'كراسة المشروع (التفاصيل الكاملة)'}
